window.MN_SEARCH = {"docs":[{"t":"g","u":"generators/gears.html","n":"Gear generator","c":"Generator","d":"Spur, helical, herringbone, bevel and worm gears, ring gears, racks and gear trains, with SVG, DXF and STL export.","k":"involute module teeth pitch pressure angle backlash train planetary idler compound holes skeleton spokes laser cut bore keyway nest","w":"Make a part to laser cut or 3D print laser cut cnc 3d print dxf svg stl fabricate export maker kinetic sculpture automata automaton","o":0,"x":"","why":"Make a part to laser cut or 3D print"},{"t":"g","u":"generators/linkages.html","n":"Linkage generator","c":"Generator","d":"Four-bar, slider-crank and multi-link mechanisms with coupler curves, link designs and export.","k":"four-bar slider crank multi link jansen coupler curve path trace grashof transmission angle rocker walking leg","w":"Draw a straight line or an ellipse straight line ellipse path curve trace guide pen plotter linkage exact straight Make a part to laser cut or 3D print laser cut cnc 3d print dxf svg stl fabricate export maker kinetic sculpture automata automaton","o":1,"x":"","why":"Draw a straight line or an ellipse · Make a part to laser cut or 3D print"},{"t":"g","u":"generators/cams.html","n":"Cam generator","c":"Generator","d":"Program rise, dwell and fall motions, pick a follower, and check pressure angle and undercut.","k":"cam follower motion program cycloidal harmonic dwell rise fall lift pressure angle undercut roller flat knife","w":"Turn rotation into back-and-forth reciprocating linear push pull piston slide stroke oscillate piston reciprocate rotary to linear Move in steps with pauses intermittent indexing stop go dwell step advance index table ratchet click film projector Make a part to laser cut or 3D print laser cut cnc 3d print dxf svg stl fabricate export maker kinetic sculpture automata automaton","o":2,"x":"","why":"Turn rotation into back-and-forth · Move in steps with pauses"},{"t":"g","u":"generators/pulleys.html","n":"Pulley generator","c":"Generator","d":"Belt drives with idlers and shared shafts, and block-and-tackle lifting systems.","k":"belt pulley idler wrap angle slip tension block and tackle lifting load sheave rope timing v-belt","w":"Connect shafts that are far apart belt chain sprocket drive power transmission distance timing belt pulley drive connect two shafts Make a part to laser cut or 3D print laser cut cnc 3d print dxf svg stl fabricate export maker kinetic sculpture automata automaton","o":3,"x":"","why":"Connect shafts that are far apart · Make a part to laser cut or 3D print"},{"t":"g","u":"generators/chains.html","n":"Chain and sprocket generator","c":"Generator","d":"Roller chain and sprockets in ANSI and ISO sizes with attachments, multiple chains and sprocket designs.","k":"roller chain sprocket ansi iso pitch attachment plate tab multi strand idler tensioner skeleton","w":"Slow down and gain force gear reduction ratio torque speed reducer gearbox slow down geared motor increase torque Connect shafts that are far apart belt chain sprocket drive power transmission distance timing belt pulley drive connect two shafts Make a part to laser cut or 3D print laser cut cnc 3d print dxf svg stl fabricate export maker kinetic sculpture automata automaton","o":3,"x":"","why":"Slow down and gain force · Connect shafts that are far apart"},{"t":"g","u":"generators/hinges.html","n":"Living hinge generator","c":"Generator","d":"Laser-cut flexure patterns that let a stiff sheet bend: straight, meander, wave, cross and fillet lattices, diamonds, fabric (Greek key) and beehive. Estimates how far it bends in your material and flags fragile or too-stiff designs.","k":"living hinge flexure kerf bending lattice slit pattern straight meander serpentine wave cross fillet diamond fabric greek key beehive honeycomb basswood birch plywood mdf acrylic bend laser cut flex test sheet pattern only svg dxf","w":"","o":null,"x":"","why":""},{"t":"g","u":"generators/gears.html#%7B%22mode%22%3A%22bevel%22%7D","n":"Gear: Bevel gears","c":"Generator","d":"A pair of cone gears for shafts that meet at an angle, cut as stacked layers or one tapered part.","k":"bevel miter right angle tredgold involute module teeth pitch pressure angle backlash train planetary idler compound holes skeleton spokes laser cut bore keyway nest","x":""},{"t":"g","u":"generators/gears.html#%7B%22mode%22%3A%22worm%22%7D","n":"Gear: Worm drive","c":"Generator","d":"A worm and wheel with 1 to 4 starts, left or right hand, as keyed layers or a twisted STL.","k":"worm wheel lead self locking reduction involute module teeth pitch pressure angle backlash train planetary idler compound holes skeleton spokes laser cut bore keyway nest","x":""},{"t":"g","u":"generators/gears.html#%7B%22ftype%22%3A%22helical%22%7D","n":"Gear: Helical gears","c":"Generator","d":"Slanted teeth for smooth, quiet running, with the helix angle shown in the STL.","k":"helical helix angle involute module teeth pitch pressure angle backlash train planetary idler compound holes skeleton spokes laser cut bore keyway nest","x":""},{"t":"g","u":"generators/gears.html#%7B%22ftype%22%3A%22herring%22%7D","n":"Gear: Herringbone gears","c":"Generator","d":"Two opposite slants in a V so the sideways pushes cancel.","k":"herringbone double helical involute module teeth pitch pressure angle backlash train planetary idler compound holes skeleton spokes laser cut bore keyway nest","x":""},{"t":"g","u":"generators/gears.html#%7B%22type%22%3A%22rack%22%7D","n":"Gear: Rack and pinion","c":"Generator","d":"A pinion driving a straight toothed rack.","k":"rack pinion linear involute module teeth pitch pressure angle backlash train planetary idler compound holes skeleton spokes laser cut bore keyway nest","x":""},{"t":"g","u":"generators/gears.html#%7B%22type%22%3A%22int%22%2C%22z1%22%3A14%2C%22z2%22%3A40%7D","n":"Gear: Ring (internal) gear","c":"Generator","d":"A pinion running inside a ring gear.","k":"ring internal annulus involute module teeth pitch pressure angle backlash train planetary idler compound holes skeleton spokes laser cut bore keyway nest","x":""},{"t":"g","u":"generators/gears.html#%7B%22gdesign%22%3A%22spokes%22%7D","n":"Gear: Skeleton gears","c":"Generator","d":"Gears with spokes or holes cut in the body to save material and weight.","k":"skeleton spokes holes lightweight pockets teardrop swirl involute module teeth pitch pressure angle backlash train planetary idler compound holes skeleton spokes laser cut bore keyway nest","x":""},{"t":"g","u":"generators/linkages.html#%7B%22kind%22%3A%22slider%22%7D","n":"Linkage: Slider-crank","c":"Generator","d":"A crank, rod and slider, with the stroke and time ratio.","k":"slider crank piston engine stroke four-bar slider crank multi link jansen coupler curve path trace grashof transmission angle rocker walking leg","x":""},{"t":"g","u":"generators/linkages.html#%7B%22kind%22%3A%22multi%22%7D","n":"Linkage: Multi-link builder","c":"Generator","d":"Build your own linkage from pivots and links and trace any point.","k":"multi link jansen walking leg sixbar four-bar slider crank multi link jansen coupler curve path trace grashof transmission angle rocker walking leg","x":""},{"t":"g","u":"generators/hinges.html#%7B%22pat%22%3A%22straight%22%2C%22out%22%3A%22sheet%22%2C%22vary%22%3A%22L%22%2C%22vals%22%3A%2210%2C%2015%2C%2020%2C%2030%22%2C%22W%22%3A30%7D","n":"Living hinge: Living hinge test sheet","c":"Generator","d":"Four straight-lattice hinges with 10, 15, 20 and 30 mm cuts side by side, to find the one that bends best in your sheet.","k":"living hinge test sheet cut length lattice living hinge flexure kerf bending lattice slit pattern straight meander serpentine wave cross fillet diamond fabric greek key beehive honeycomb basswood birch plywood mdf acrylic bend laser cut flex test sheet pattern only svg dxf","x":""},{"t":"g","u":"generators/hinges.html#%7B%22pat%22%3A%22wave%22%2C%22out%22%3A%22pattern%22%7D","n":"Living hinge: Wavy slit hinge pattern","c":"Generator","d":"Just the pattern, ready to paste over the place on your part that should bend.","k":"wavy slit pattern paste living hinge flexure kerf bending lattice slit pattern straight meander serpentine wave cross fillet diamond fabric greek key beehive honeycomb basswood birch plywood mdf acrylic bend laser cut flex test sheet pattern only svg dxf","x":""},{"t":"g","u":"generators/pulleys.html#%7B%22mode%22%3A%22lift%22%7D","n":"Pulley: Block and tackle","c":"Generator","d":"Lifting systems with mechanical advantage, effort and rope pulled.","k":"block tackle lifting hoist winch mechanical advantage belt pulley idler wrap angle slip tension block and tackle lifting load sheave rope timing v-belt","x":""},{"t":"m","u":"pages/geneva-drive.html","n":"Geneva Drive","c":"Intermittent motion","d":"Turns steady rotation into a series of exact steps with pauses between them","k":"geneva maltese cross indexing","w":"Move in steps with pauses intermittent indexing stop go dwell step advance index table ratchet click film projector","o":0,"x":"Two wheels: the driver carries a pin and a raised locking disc. The driven Geneva wheel has straight slots and curved notches between them. The driver turns at a steady speed. Once per turn its pin slides into a slot, swings the wheel round by one slot spacing, then slides back out. While the pin is out of the slots, the locking disc sits in one of the curved notches, so the wheel cannot drift. This rest is called the dwell. Good to know: the pin enters each slot moving straight along it, so the wheel starts and stops smoothly instead of with a bang. With four slots the wheel moves for only a quarter of each driver turn and rests for the other three quarters. Try it: watch the motion graph peak in the middle of each step. In Do the math, change the number of slots: more slots give smaller steps and longer rests. Film projectors, to hold each frame still while it is shown Indexing tables that move parts between machining stations Pen plotters and older mechanical counters The name comes from Swiss watchmaking. A \"Geneva stop\", a Geneva wheel with one slot left uncut, was used to stop a watch mainspring from being wound too tight.","why":"Move in steps with pauses"},{"t":"m","u":"pages/slider-crank.html","n":"Slider Crank","c":"Linkages","d":"Turns rotation into back-and-forth motion, or back-and-forth into rotation","k":"piston engine crank slider","w":"Turn rotation into back-and-forth reciprocating linear push pull piston slide stroke oscillate piston reciprocate rotary to linear Work slowly, return quickly quick return shaper cutting stroke time ratio return stroke saw planer","o":0,"x":"A crank of length r turns about a fixed centre. A connecting rod of length l joins its tip to a slider. The slider moves on a straight line through the crank centre. Its stroke is 2r. The slider is not a pure sine wave. The longer the rod, the closer it gets to one. Good to know: at each end of the stroke the crank and rod line up (the dead centres). A push on the slider there cannot start the crank turning, which is why engines carry a heavy flywheel to roll through. Try it: change the rod length with the control to see the motion flatten or skew. Piston engines, where the slider is the piston Air compressors and reciprocating pumps Jigsaws and sewing-machine needle bars A stone relief at Hierapolis in Turkey, from the 3rd century AD, shows a water-powered sawmill using a crank and connecting rod. It is the oldest known picture of this mechanism.","why":"Turn rotation into back-and-forth · Work slowly, return quickly"},{"t":"m","u":"pages/four-bar.html","n":"Four-Bar Linkage","c":"Linkages","d":"Turns a turning crank into a rocking lever, or guides a point along a chosen path","k":"four bar fourbar rocker crank coupler grashof","w":"Make something walk walk walking leg legs robot theo jansen strandbeest crawl step animal creature","o":1,"x":"Four rigid bars joined in a loop by four pivots. One bar is fixed (the frame). The crank is driven, the coupler floats, and the rocker swings. As the crank goes round, the coupler pushes and pulls the rocker back and forth through a fixed arc. Whether any bar can make full turns depends only on the lengths. The Grashof test checks it: shortest + longest must be no more than the other two added together. Every point on the coupler draws its own closed path, its coupler curve. The red point P shows one. Designers choose a point whose path matches a job. Good to know: keep the transmission angle between about 40° and 140°. Outside that range most of the force goes into the pivots instead of moving the rocker, and the linkage feels stiff or jams. Try it: enter your own bar lengths in Do the math to see the Grashof result, the rocker swing and the time ratio. Windscreen wipers and oil-field pumpjacks Bicycle rear suspension and folding chairs Excavator buckets and car bonnet hinges Your knee works like a crossed four-bar linkage. The two cruciate ligaments inside it act as the crossed bars, which is why the knee rolls and slides instead of hinging about one fixed point.","why":"Make something walk"},{"t":"m","u":"pages/scotch-yoke.html","n":"Scotch Yoke","c":"Linkages","d":"Turns rotation into perfectly smooth sine-wave back-and-forth motion","k":"scotch yoke slotted","w":"Turn rotation into back-and-forth reciprocating linear push pull piston slide stroke oscillate piston reciprocate rotary to linear Draw a straight line or an ellipse straight line ellipse path curve trace guide pen plotter linkage exact straight","o":1,"x":"A crank carries a pin. The yoke is a frame with a slot cut across it, held in guides so it can only slide one way. As the crank turns, the pin slides along the slot and at the same time pushes the yoke sideways. Only the sideways part of the pin's circle reaches the yoke. So the yoke position is exactly r cos θ: pure simple harmonic motion. The slider crank (M-02) only comes close to this. Good to know: there is no connecting rod, so it is short and compact. The cost is the pin rubbing in the slot, which needs lubrication and wears over time. Try it: change the crank radius. The stroke is always 2r, and the motion graph stays a perfect sine wave. Valve actuators on pipelines Shaking and vibration test rigs Some compact pumps and engines Look at a spinning merry-go-round from the side and each horse appears to slide back and forth in exactly the Scotch yoke's motion. It is the same sine-wave motion as a weight bouncing on a spring.","why":"Turn rotation into back-and-forth · Draw a straight line or an ellipse"},{"t":"m","u":"pages/cam-follower.html","n":"Cam and Follower","c":"Cams","d":"Turns rotation into any up-and-down motion you can draw","k":"cam follower lobe","w":"Turn rotation into back-and-forth reciprocating linear push pull piston slide stroke oscillate piston reciprocate rotary to linear Move in steps with pauses intermittent indexing stop go dwell step advance index table ratchet click film projector","o":2,"x":"The cam is a shaped disc on a turning shaft. The follower rests on its edge and is guided so it can only move up and down. A spring or gravity keeps it pressed on. At every moment the follower's height equals the cam's radius at the contact point, so the cam's outline is really a recipe for the motion. This cam has four parts: a rise, a dwell at the top, a fall and a dwell at the bottom. Good to know: the rise follows a smooth (cycloidal) curve that starts and ends with zero speed and zero acceleration, so the follower does not knock. Steep outlines push the follower sideways (a high pressure angle), so big lifts need bigger cams. Try it: change the lift and see the outline grow. To design your own cam and export it, open the Cam generator. Engine valves, opened by the camshaft Sewing machines, looms and packaging machines Automata and kinetic sculptures Maillardet's automaton (around 1800, now at the Franklin Institute) is a mechanical boy that draws four pictures and writes three poems. Every pen stroke is stored in the outline of a stack of brass cams.","why":"Turn rotation into back-and-forth · Move in steps with pauses"},{"t":"m","u":"pages/jansen-linkage.html","n":"Jansen Linkage","c":"Walking","d":"Turns one turning crank into a walking step","k":"strandbeest theo jansen walking leg","w":"Make something walk walk walking leg legs robot theo jansen strandbeest crawl step animal creature","o":0,"x":"One crank, eight bars and two rigid triangles, all joined by pivots to a fixed frame. The bottom corner of the lower triangle is the foot. The crank turns at constant speed and the bars pass the motion down the leg. The foot traces a flattened loop: a long, almost straight bottom and a higher arch on top. Along the straight part the foot moves backwards at nearly constant height. That pushes the machine forward without it bobbing up and down. Good to know: the foot is on the ground for a bit under half of each turn, so walking machines put several legs on one crankshaft, out of step, so some feet are always down. Only the ratios of the bar lengths matter. Scale them all and the leg works at any size. Try a different crank length in Do the math to see stride and speed change. Theo Jansen's wind-walking Strandbeest sculptures Walking toys and robot kits Research into legged robots for soft or uneven ground Theo Jansen builds his Strandbeests from yellow plastic electrical conduit. He found the leg proportions in 1990 by letting a computer \"evolve\" thousands of random legs and keep the best walkers.","why":"Make something walk"},{"t":"m","u":"pages/ratchet-pawl.html","n":"Ratchet and Pawl","c":"Intermittent motion","d":"Lets a wheel turn one way only and moves it in clicks","k":"ratchet pawl click one way","w":"Move in steps with pauses intermittent indexing stop go dwell step advance index table ratchet click film projector Allow one direction only, or hold a position one way lock hold brake backstop self locking prevent reverse back driving ratchet","o":0,"x":"A ratchet wheel with sloped, saw-like teeth; a lever that swings about the wheel centre; a driving pawl on the lever and a holding pawl on the frame. Small springs keep both pawls against the teeth. Swing the lever forward and the driving pawl catches a tooth and pushes the wheel along. Swing it back and the pawl rides up the slope of the next tooth and drops in behind it with a click. The holding pawl stops the wheel running backwards meanwhile. Good to know: the wheel can only move in whole teeth. Finer teeth give smaller steps, but each tooth carries less load. Try it: in Do the math, see how lever length and drum size change the pull and lifting speed of a hand winch. Socket wrenches and bicycle freewheels Winches, car jacks and hand-brake levers Cable ties, which are a straight ratchet Richard Feynman used a tiny imaginary ratchet to explain why you cannot get free energy from heat. Shaken by random molecule hits at one temperature, the pawl bounces too, and the wheel goes nowhere on average.","why":"Move in steps with pauses · Allow one direction only, or hold a position"},{"t":"m","u":"pages/belt-pulleys.html","n":"Belt and Pulleys","c":"Transmission","d":"Carries rotation between shafts some distance apart and changes the speed","k":"belt pulley block tackle v-belt","w":"Connect shafts that are far apart belt chain sprocket drive power transmission distance timing belt pulley drive connect two shafts Lift or pull a load lift hoist winch crane block and tackle load weight raise lower pull mechanical advantage jack","o":0,"x":"Two pulleys on parallel shafts and a loop of belt stretched round them. The belt's tension creates the grip that carries the drive. The belt moves at one speed, so both pulley rims move at the same surface speed. The smaller pulley has to spin faster to keep up. Speed ratio = driver diameter ÷ driven diameter. Torque goes the other way: the slower pulley gets more torque. An open belt keeps both pulleys turning the same way. A crossed belt reverses the driven pulley, but rubs where it crosses, so it suits light loads. Good to know: a smooth belt can slip a little under heavy load. That protects a machine if it jams, but when exact timing matters a toothed belt is used (see the Timing Belt element). Try it: change the driven pulley size and switch between open and crossed. Lathes, drill presses and older factory line-shafts Car engine accessories (alternator, water pump) Washing machines and treadmills Your fingers have pulleys too. Each finger's flexor tendon runs through a row of tough rings called pulleys that hold it close to the bone, and rock climbers are known for straining them.","why":"Connect shafts that are far apart · Lift or pull a load"},{"t":"m","u":"pages/planetary-gears.html","n":"Planetary Gear Train","c":"Gears","d":"Gets large or switchable speed ratios from a compact set of gears","k":"epicyclic sun planet ring carrier gearbox","w":"Slow down and gain force gear reduction ratio torque speed reducer gearbox slow down geared motor increase torque Share one drive between two outputs differential split torque two wheels cornering axle car robot drive average speed","o":1,"x":"A sun gear in the centre, planet gears round it, a carrier that holds the planets' axles, and a ring gear with teeth on the inside. Hold one of the three main parts (sun, carrier or ring), drive another, and take the output from the third. Each choice gives a different ratio. With the ring held, sun in and carrier out: carrier speed = sun × Ns ÷ (Ns + Nr). Here 24 and 48 teeth give 3 : 1. Hold the carrier and the ring turns backwards at half the sun speed. Hold the sun and the carrier turns a little slower than the ring. Good to know: the load is shared between several planets, so the set is small for the torque it carries. Automatic gearboxes change gear by clamping different parts with brakes and clutches. Try it: switch which part is held and compare the speeds. Automatic car gearboxes and hybrid car drives Bicycle hub gears and electric screwdrivers Robot joints and wind-turbine gearboxes The Antikythera mechanism, an ancient Greek astronomical calculator from around 2,100 years ago, used gears riding on another gear with a pin-and-slot to copy the Moon's changing speed across the sky.","why":"Slow down and gain force · Share one drive between two outputs"},{"t":"m","u":"pages/peaucellier.html","n":"Peaucellier–Lipkin Linkage","c":"Linkages","d":"Draws a perfectly straight line using nothing but pivots","k":"peaucellier lipkin inversor straight line","w":"Draw a straight line or an ellipse straight line ellipse path curve trace guide pen plotter linkage exact straight","o":0,"x":"A fixed pivot O, two equal long bars from O, a diamond (rhombus) of four equal short bars, and an input lever that guides corner Q round a circle. The geometry keeps OQ × OP constant. Mathematicians call P the inverse of Q. Inversion turns any circle that passes through O into a straight line. Q moves on such a circle, so P is forced onto an exact straight line. Good to know: before 1864 every straight-line linkage, including James Watt's, was only approximately straight. This one is exact and has no sliding guides to wear. Try it: change the input swing to draw a longer or shorter line. Precision drawing and measuring instruments Straight-line guides where a sliding track would bind or wear Teaching geometric inversion In 1876 Alfred Kempe proved that, in principle, a linkage of bars and pivots can trace any curve made of algebraic equations. Mathematicians like to say that means some linkage could sign your name.","why":"Draw a straight line or an ellipse"},{"t":"m","u":"pages/trammel.html","n":"Trammel of Archimedes","c":"Linkages","d":"Two sliders on crossed tracks guide a pen around an ellipse","k":"trammel archimedes ellipse","w":"Draw a straight line or an ellipse straight line ellipse path curve trace guide pen plotter linkage exact straight","o":5,"x":"A cross with two straight slots at right angles, a sliding block in each slot, and a rod pinned to both blocks with a pen on it. Each block can only move along its own slot. As the rod turns, the pen is pulled round an oval: an ellipse. The ellipse's half-widths equal the pen's distances to the two pins, so sliding the pen along the rod sets its shape. Good to know: with the pen halfway between equal arms the ellipse becomes a circle. With the pen on a pin it simply runs along that slot. Try it: move the pen along the rod and watch the shape change. The Tusi couple (M-18) makes the same motion with gears. Ellipsographs for drawing ellipses Woodworking jigs for cutting oval frames and table tops Teaching the geometry of the ellipse A folk toy called the \"Kentucky do-nothing\" or \"nothing grinder\" is a trammel with a handle. Crank it and the blocks slide busily while nothing useful happens.","why":"Draw a straight line or an ellipse"},{"t":"m","u":"pages/quick-return.html","n":"Quick Return","c":"Linkages","d":"Makes the working stroke slow and the return stroke fast","k":"quick return whitworth shaper","w":"Work slowly, return quickly quick return shaper cutting stroke time ratio return stroke saw planer","o":0,"x":"A crank turning at steady speed, a block on its pin, a slotted arm that rocks about a pivot below the crank, and a link from the arm tip to a ram on a slide. The block slides in the arm's slot and rocks the arm from side to side. Because the arm's pivot sits outside the crank circle, the crank turns through a bigger angle while pushing one way than the other. So the forward, working stroke takes longer and the return is quicker. Less time is lost on the stroke that does no work. Good to know: the time ratio depends only on the crank radius and the distance to the arm pivot. A bigger crank gives a longer stroke and a bigger difference between the two strokes. Try it: change the crank radius and watch the stroke and the motion graph. Metal shaping and slotting machines Power hacksaws Packaging machines that push products quickly back into place A close cousin, the Whitworth quick return, is named after Joseph Whitworth, the same engineer who created the world's first national standard for screw threads in 1841.","why":"Work slowly, return quickly"},{"t":"m","u":"pages/spur-gears.html","n":"Spur Gears","c":"Gears","d":"Passes rotation between parallel shafts and changes speed and turning direction","k":"gear teeth involute meshing","w":"Slow down and gain force gear reduction ratio torque speed reducer gearbox slow down geared motor increase torque","o":0,"x":"Two toothed wheels on parallel shafts. The sides of the teeth follow a curve called an involute. As teeth push on each other the gears behave like two discs rolling without slipping. These imaginary discs are the pitch circles, and they touch at the pitch point. Speed ratio = driven teeth ÷ driver teeth. The bigger gear turns slower and with more torque. Meshing gears turn opposite ways. Good to know: the involute shape keeps the speed ratio perfectly steady even if the gears sit slightly too far apart. Two gears only mesh if their teeth are the same size (the same module). Try it: change both tooth counts and watch the speeds in the graph. To design and export gears, open the Gear generator. Gearboxes, clocks and kitchen mixers Printers, cameras and toys Mills, winches and machine tools Gears were found in nature in 2013: young planthopper insects (Issus coleoptratus) have a strip of gear teeth on their two back legs that mesh when they jump, so both legs kick at exactly the same moment.","why":"Slow down and gain force"},{"t":"m","u":"pages/worm-gear.html","n":"Worm Gear","c":"Gears","d":"Turns motion through a right angle with a big speed reduction in one step","k":"worm wheel self locking","w":"Slow down and gain force gear reduction ratio torque speed reducer gearbox slow down geared motor increase torque Turn the motion through an angle right angle 90 degrees corner bevel miter universal joint shaft angle change direction Allow one direction only, or hold a position one way lock hold brake backstop self locking prevent reverse back driving ratchet","o":1,"x":"The worm is a screw on the input shaft. The worm wheel is a gear with slanted teeth that match the thread. The two shafts cross at 90° without meeting. Each turn of the worm slides its thread along and pushes the wheel round by as many teeth as the worm has starts. Ratio = wheel teeth ÷ worm starts. 24 teeth and one start gives 24 : 1 in a single compact step. Good to know: the teeth slide more than they roll, so worm drives run warmer and lose more power than spur gears. With a single start, friction often stops the wheel from turning the worm backwards, so it holds its load without a brake. Try it: add starts and see the ratio drop and the wheel speed up. Guitar tuning pegs Lifts, gates and conveyor drives Steering boxes and rotating stages Arthur Ganson's sculpture \"Machine with Concrete\" chains twelve 50 : 1 worm reductions. The motor spins at about 200 rpm, while the last gear, set in a block of concrete, would need over two trillion years to turn once.","why":"Slow down and gain force · Turn the motion through an angle"},{"t":"m","u":"pages/rack-pinion.html","n":"Rack and Pinion","c":"Gears","d":"Turns rotation into straight-line motion, or straight-line into rotation","k":"","w":"Turn rotation into back-and-forth reciprocating linear push pull piston slide stroke oscillate piston reciprocate rotary to linear Lift or pull a load lift hoist winch crane block and tackle load weight raise lower pull mechanical advantage jack","o":2,"x":"A round gear (the pinion) and a straight toothed bar (the rack). The rack is like a gear with an infinitely large radius. As the pinion turns, its pitch circle rolls along the rack's pitch line without slipping and pushes the rack sideways. Each full turn moves the rack by the pitch-circle circumference: π × module × teeth. Good to know: it works both ways. Push the rack and the pinion turns, which is how you feel the road through a car's steering. The small gap between teeth (backlash) shows up as play when you reverse. Try it: more pinion teeth give more travel per turn but less push for the same torque. Car steering Lathe carriages, CNC routers and 3D printers Sliding gates and rack railways The Pilatus railway in Switzerland, with slopes up to 48%, is the steepest rack railway in the world. Its pinions are laid flat and grip the rack from both sides so they cannot climb out of the teeth.","why":"Turn rotation into back-and-forth · Lift or pull a load"},{"t":"m","u":"pages/roller-chain.html","n":"Roller Chain","c":"Chains","d":"Carries power between distant shafts with a loop of linked rollers","k":"chain sprocket bicycle","w":"Connect shafts that are far apart belt chain sprocket drive power transmission distance timing belt pulley drive connect two shafts","o":0,"x":"A closed loop of links, each with rollers on pins between side plates, and two sprockets whose teeth fit between the rollers. The rollers sit in the tooth gaps, so the chain cannot slip. It moves one link for every tooth that passes. Ratio = driven teeth ÷ driver teeth, the same rule as gears. Unlike meshing gears, both sprockets turn the same way and the shafts can be far apart. Good to know: the chain wraps a sprocket as a many-sided polygon, not a circle, so its speed ripples slightly with each tooth. Small sprockets ripple most, which is why fast drives use about 17 teeth or more. Try it: change both tooth counts. The drawing finds a shaft distance that fits a whole number of links. Bicycles and motorcycles Conveyors and farm machinery Engine camshaft drives Leonardo da Vinci sketched chain links in the 1500s, but the modern bush roller chain was patented by Hans Renold in 1880. The basic design on your bicycle has changed very little since.","why":"Connect shafts that are far apart"},{"t":"m","u":"pages/double-hookes-joint.html","n":"Double Hooke's Joint","c":"Joints","d":"Two universal joints in a row: the second cancels the speed wobble of the first","k":"universal joint u-joint cardan driveshaft","w":"Turn the motion through an angle right angle 90 degrees corner bevel miter universal joint shaft angle change direction Join shafts that do not line up coupling misaligned offset parallel shafts flexible coupling oldham universal joint motor to lead screw z wobble","o":1,"x":"Three shafts joined by two universal joints. Each joint is a cross with four arms held in two forked yokes. One joint turning a corner makes the output speed up and slow down twice per turn, even with a steady input. The bigger the angle, the bigger the wobble. Add a second joint at the same angle, with the middle shaft's two yokes lined up, and its wobble is exactly opposite. The output matches the input again. Good to know: the middle shaft still speeds up and slows down; only the two ends are smooth. If the yokes are assembled 90° apart, the wobble doubles instead of cancelling. Try it: change the joint angle, then switch the yokes to \"At 90°\" to see what a wrong assembly does. Car and truck drive shafts Steering columns Machine tools and agricultural power take-offs Robert Hooke described his \"universal joint\" in 1676 in a booklet about helioscopes, instruments for safely watching the Sun. Gerolamo Cardano had described a similar gimbal more than a century earlier, which is why it is also called a Cardan joint.","why":"Turn the motion through an angle · Join shafts that do not line up"},{"t":"m","u":"pages/tusi-couple.html","n":"Tusi Couple","c":"Gears","d":"A gear rolling inside a ring twice its size turns rotation into an exact straight line","k":"tusi couple hypocycloid cardano","w":"Draw a straight line or an ellipse straight line ellipse path curve trace guide pen plotter linkage exact straight","o":4,"x":"A fixed ring gear with teeth on the inside, a gear half its size rolling inside it, and a carrier arm that holds the small gear's centre and turns about the ring centre. As the carrier goes round, the small gear rolls on the ring and spins backwards on its own axle exactly as fast as the carrier turns forwards. So any point on the small gear's pitch circle runs back and forth along a straight diameter of the ring, in simple harmonic motion. Points inside the small gear, like E, trace ellipses, and its centre traces a circle. The Trammel of Archimedes (M-11) makes the same motion with sliders. Good to know: it gives straight-line motion from a turning shaft with no sliding parts at all. Cardan gear drives in some compact engines and pumps Printing and packaging machines that need straight strokes Teaching astronomy and the history of science Nasir al-Din al-Tusi described this device in 1247 to model planetary motion with circles only. Nearly 300 years later Copernicus used the same construction in his book on the movement of the planets.","why":"Draw a straight line or an ellipse"},{"t":"m","u":"pages/watts-linkage.html","n":"Watt's Linkage","c":"Linkages","d":"Two swinging arms and a short link guide a point along an almost straight line","k":"watt watts parallel motion straight line beam engine panhard rear axle","w":"Draw a straight line or an ellipse straight line ellipse path curve trace guide pen plotter linkage exact straight","o":1,"x":"Two equal arms swing about fixed pivots on opposite sides. A short link joins their tips, and the point P halfway along it is the output. Each arm tip moves on an arc, but the two arcs bend opposite ways. Halfway between them the bends cancel, so P moves very nearly straight up and down. If the arms swing too far, P leaves the line and the full path turns into a figure of eight. The straight part is the middle of the eight. Good to know: the line is only approximate, but it uses pivots only. Pivots are cheap, stiff and easy to make accurate, unlike long sliding guides. Try it: change the arm length and the middle link. The motion graph shows how far P strays sideways, in millimetres, as it moves. Guiding the piston rod of early beam steam engines Locating the rear axle of cars and race cars from side to side (a Watt's link) Suspension of trailers and some bicycles James Watt patented this linkage in 1784 for his beam engines. Years later he wrote to his son that he was prouder of it than of any other mechanical invention he had made.","why":"Draw a straight line or an ellipse"},{"t":"m","u":"pages/chebyshev-linkage.html","n":"Chebyshev Linkage","c":"Linkages","d":"A crossed four-bar linkage whose middle point moves along an almost straight line","k":"chebyshev tchebycheff straight line approximate four bar lambda","w":"Draw a straight line or an ellipse straight line ellipse path curve trace guide pen plotter linkage exact straight","o":2,"x":"A four-bar linkage with crossed side links. The fixed frame, the two side links and the short top link have lengths in the ratio 2 : 2.5 : 2.5 : 1. As the side links rock, the middle point P of the top link moves sideways along a nearly straight, level line, then comes back along it. Pafnuty Chebyshev chose these lengths with his own theory of best approximation, so the path stays as close to straight as possible over the stroke. Good to know: over the middle of the stroke P strays from a straight line by only a tiny fraction of the frame length. Swinging further gives a longer stroke but a less straight one. Try it: change the swing. The graph shows the height of P, which barely changes while P travels along the line. Straight-line guides for pens, sensors and light loads Walking machines and toy walkers (its cousin, the lambda linkage) Teaching linkage synthesis Chebyshev showed a walking machine called the plantigrade machine at the 1878 Paris World's Fair. It used a close relative of this linkage to give its feet a flat, level step.","why":"Draw a straight line or an ellipse"},{"t":"m","u":"pages/pantograph.html","n":"Pantograph","c":"Linkages","d":"A parallelogram of bars copies a drawing at a larger or smaller scale","k":"pantograph copy scale enlarge reduce engraving key copier","w":"Draw a straight line or an ellipse straight line ellipse path curve trace guide pen plotter linkage exact straight","o":3,"x":"Four bars form a parallelogram, with one corner extended. A fixed pivot O, a tracing point T and a pen P all sit on one straight line. Because the parallelogram keeps its sides parallel, P always stays on the line through O and T, and its distance from O is always the same multiple of T's distance. So whatever shape T traces, P draws the same shape scaled up by that factor. Swap T and P to scale down instead. Good to know: the scale is set by where the bars are joined, not by their total length. Any play in the pivots is scaled up too, so tight pivots matter. Try it: switch the scale between 2× and 3× and watch both paths. The dashed line shows that O, T and P stay in line. Engraving and copy-milling machines that cut letters from a template Key-cutting machines that copy a key Drawing enlargers, and the folding arms of desk lamps and wall mirrors The astronomer Christoph Scheiner described the pantograph in the early 1600s. The word is also used for the folding arm on the roof of an electric train, which looks similar but does a different job.","why":"Draw a straight line or an ellipse"},{"t":"m","u":"pages/toggle-clamp.html","n":"Toggle Clamp","c":"Linkages","d":"Two links pushed into a straight line give an enormous clamping force that locks itself","k":"toggle clamp over centre over center locking pliers vise grip destaco hold down","w":"Allow one direction only, or hold a position one way lock hold brake backstop self locking prevent reverse back driving ratchet","o":3,"x":"A handle turns about a pivot and pushes a short link, and the link pushes a plunger. When the handle is down, the handle pivot, the link and the plunger line up. Near that straight line the plunger hardly moves for a big turn of the handle. Since work in equals work out, a small hand force becomes a huge force on the plunger. Push the handle just past the straight line, against a stop, and the clamp locks. The force from the work now pushes the handle further onto the stop instead of opening it. This is called going over centre. Good to know: real clamps are adjusted so the plunger meets the work just before the line-up. The last few degrees of handle movement build the clamping force. Try it: watch the force gain on the graph climb steeply as the links line up. Workholding clamps on jigs, welding fixtures and machine tables Locking pliers Latches on toolboxes, ski boots and window catches Locking pliers, invented by William Petersen in Nebraska in 1924, use exactly this over-centre trick. The screw in the handle sets where the links line up.","why":"Allow one direction only, or hold a position"},{"t":"m","u":"pages/bevel-gears.html","n":"Bevel Gears","c":"Gears","d":"Cone-shaped gears that send rotation around a corner, usually at 90°","k":"bevel mitre miter cone gear right angle 90 degree hand drill","w":"Turn the motion through an angle right angle 90 degrees corner bevel miter universal joint shaft angle change direction Join shafts that do not line up coupling misaligned offset parallel shafts flexible coupling oldham universal joint motor to lead screw z wobble","o":0,"x":"Each gear is cut on a cone instead of a cylinder. The two cones meet at a shared tip, the apex, where the two shaft lines cross. The teeth roll on each other along the cone surfaces. Like spur gears, the speed ratio is the tooth count of the driven gear divided by the driver's. For shafts at 90°, the pitch cone angles add up to 90°: the smaller gear has the narrower cone. Two equal gears at 90° are called mitre gears. Good to know: both gears must point at the same apex, so the shaft positions along their length matter. Set them with shims until the backlash is right. Try it: change the tooth counts. The cone angles change so the two cones still meet at one point. Car rear axles (as spiral or hypoid bevels) and differentials Hand drills, angle grinders and kitchen mixers Right-angle drives in machines and kinetic sculptures A hand-cranked \"eggbeater\" drill uses one large bevel gear driving a small one, so one turn of the crank spins the chuck several times.","why":"Turn the motion through an angle · Join shafts that do not line up"},{"t":"m","u":"pages/differential.html","n":"Differential","c":"Gears","d":"Lets two wheels on one drive turn at different speeds while sharing the push","k":"differential diff open differential spider gear axle car cornering limited slip","w":"Share one drive between two outputs differential split torque two wheels cornering axle car robot drive average speed","o":0,"x":"The engine turns a carrier (the case). Inside it, small spider gears are mounted on a cross-pin and mesh with two side gears, one on each axle. Going straight, the spider gears do not spin on their pin. The whole case turns as one, and both wheels go at the case speed. In a turn the outer wheel must go further. The spider gears start to spin, so one side gear speeds up by exactly as much as the other slows down. The average of the two wheel speeds always equals the case speed. Good to know: an open differential always sends equal torque to both wheels. If one wheel spins on ice, the other gets only that small torque too, which is why off-road vehicles use locking or limited-slip differentials. Try it: change the turn. The graph shows both wheel speeds, and their average stays on the case speed. Car and truck axles, between the left and right wheels Between the front and rear axles of four-wheel drives Mechanical calculators, and the south-pointing chariot The Chinese south-pointing chariot used a differential gear train so a pointing figure kept facing the same direction while the chariot turned. Onésime Pecqueur patented the car differential in France in 1827.","why":"Share one drive between two outputs"},{"t":"m","u":"pages/intermittent-gear.html","n":"Intermittent Gear","c":"Intermittent motion","d":"A gear with only some of its teeth turns the other gear in steps, then lets it rest","k":"intermittent mutilated gear partial gear counter odometer index","w":"Move in steps with pauses intermittent indexing stop go dwell step advance index table ratchet click film projector","o":1,"x":"The driver has teeth on only part of its edge. The rest is a smooth arc. The driven gear has a full set of teeth. While the toothed part passes, the two gears mesh and the driven gear turns. When the smooth part passes, the driven gear stops. Each turn of the driver moves the driven gear by the number of driver teeth divided by the driven tooth count. Good to know: on its own the driven gear can drift while it rests. Real designs add a locking arc on the driver and a matching scoop on the driven gear, as in the Geneva drive (M-01). The first tooth also hits hard, so it is best for light, slow loads. Try it: change the number of teeth on the driver. More teeth make longer steps and shorter rests. Mechanical counters and odometers, where one wheel carries to the next Indexing in toys, automata and packaging machines Film and paper advance in simple machines In an old mechanical car odometer, each number wheel has a two-tooth patch that nudges the next wheel on by one digit as it passes from 9 to 0.","why":"Move in steps with pauses"},{"t":"m","u":"pages/sun-and-planet.html","n":"Sun and Planet Gear","c":"Gears","d":"A gear fixed to a connecting rod orbits a gear on the shaft and turns it twice per stroke","k":"sun and planet gear watt murdoch beam engine","w":"Turn rotation into back-and-forth reciprocating linear push pull piston slide stroke oscillate piston reciprocate rotary to linear","o":6,"x":"A planet gear is bolted to the bottom of a connecting rod, so it cannot spin on its own. It meshes with a sun gear fixed to the output shaft. A link keeps the two gears in mesh. As the rod goes up and down, the planet is carried round the sun without turning, and its teeth roll the sun round. With two gears the same size, the sun makes two turns for every trip of the planet around it. Good to know: the doubling let a slow engine drive a faster flywheel, and it turned up-and-down motion into rotation without using a crank. Try it: change the planet size. A larger planet makes the sun turn more times per stroke. James Watt's rotative beam engines from 1781 Teaching epicyclic gearing (the planetary gear train, M-09) Kinetic sculptures and models that need a speed-up William Murdoch, who worked for Watt, invented this gear in 1781. Watt used it because another inventor, James Pickard, held a patent on using a crank for this job.","why":"Turn rotation into back-and-forth"},{"t":"m","u":"pages/oldham-coupling.html","n":"Oldham Coupling","c":"Joints","d":"A sliding middle disc connects two parallel shafts that are slightly out of line","k":"oldham coupling misalignment offset shaft coupler","w":"Join shafts that do not line up coupling misaligned offset parallel shafts flexible coupling oldham universal joint motor to lead screw z wobble","o":0,"x":"Each shaft has a hub with a slot across its face. A middle disc has a tongue on each side, at 90° to each other, that slide in the two slots. The input hub turns the disc through one tongue, and the disc turns the output hub through the other. Both shafts turn at exactly the same speed. If the shafts are offset, the disc slides back and forth in both slots while it turns. Its centre runs round a small circle, twice per turn. Good to know: it passes speed through perfectly, with no wobble in speed, unlike a single universal joint. The sliding causes wear, so the disc is often made of acetal or nylon. Try it: change the offset between the shafts and watch the disc slide. With zero offset nothing slides. Couplings between motors and lead screws in 3D printers and CNC machines Pumps and compressors, including scroll compressors Small encoders and instruments The Irish engineer John Oldham invented this coupling around 1820 for the paddle steamers he worked on in Dublin.","why":"Join shafts that do not line up"},{"t":"m","u":"pages/anchor-escapement.html","n":"Anchor Escapement","c":"Intermittent motion","d":"A swinging pendulum lets a toothed wheel advance one tooth at a time, giving a clock its tick","k":"escapement anchor pendulum clock tick tock pallet escape wheel","w":"Move in steps with pauses intermittent indexing stop go dwell step advance index table ratchet click film projector","o":2,"x":"A toothed escape wheel is pushed round by the clock weight or spring. An anchor, rocked by the pendulum, has two pallets that dip in and out of the wheel teeth. As the pendulum swings, one pallet lifts out and lets a tooth slip past. The other pallet drops in and catches the next tooth. Each swing lets the wheel advance by half a tooth. As each tooth slides off a pallet, it gives the anchor a small push. This push keeps the pendulum swinging against friction. Good to know: the pendulum, not the wheel, sets the timing. A pendulum about 994 mm long takes one second per swing, which is why tall longcase clocks are that size. Try it: watch the graph. The wheel moves in quick steps and rests while the pendulum swings on. Pendulum clocks, from longcase clocks to wall clocks Metronomes and some mechanical timers Kinetic sculptures that need a slow, steady drive The anchor escapement appeared in English clocks around 1670, credited to Robert Hooke or the clockmaker William Clement. It let pendulums swing in small arcs, which made clocks far more accurate.","why":"Move in steps with pauses"},{"t":"m","u":"pages/eccentric.html","n":"Eccentric and Strap","c":"Cams","d":"An off-centre disc inside a ring works like a tiny crank and pushes a rod back and forth","k":"eccentric strap sheave valve gear stephenson","w":"Turn rotation into back-and-forth reciprocating linear push pull piston slide stroke oscillate piston reciprocate rotary to linear","o":4,"x":"A round disc, the eccentric, is fixed to a shaft but off its centre by a distance e. A ring, the strap, fits around the disc and is joined to a rod. As the shaft turns, the disc centre goes round a small circle of radius e. The strap follows it and pushes the rod back and forth, just like a slider crank (M-02) with a crank of length e. So the stroke is 2e. Since the disc surrounds the shaft, the shaft can carry on through, which a normal crank does not allow. Good to know: it is good for short strokes on a shaft that must stay continuous. The strap slides around the whole disc, so it needs a large bearing area and oil, or a ball bearing. Try it: change the eccentricity e and the rod length. The stroke is always twice the offset. Valve gear on steam locomotives and engines Fuel and oil pumps driven from a camshaft Jaw crushers, vibrating screens and power presses Stephenson's valve gear, used on thousands of steam locomotives, uses two eccentrics on the axle. Sliding a link between them reverses the engine and sets how long steam is let in.","why":"Turn rotation into back-and-forth"},{"t":"m","u":"pages/swashplate.html","n":"Swashplate","c":"Cams","d":"A tilted plate on a turning shaft pushes a ring of pistons in and out in turn","k":"swashplate swash plate wobble plate axial piston pump helicopter","w":"Turn rotation into back-and-forth reciprocating linear push pull piston slide stroke oscillate piston reciprocate rotary to linear","o":5,"x":"A flat plate is fixed to a shaft at an angle. Pistons sit in a ring around the shaft, parallel to it, with their ends resting on the plate. As the shaft turns, the tilted plate gets nearer to some pistons and further from others, so each piston moves in and out once per turn. The stroke is 2 × R × tan α, where R is the radius of the piston ring and α is the tilt. The pistons move in a smooth sine wave, each one a little later than its neighbour. Good to know: changing the tilt while it runs changes the stroke, and with it the flow of a pump. Set to zero tilt, the pistons do not move at all. Try it: change the tilt and the number of pistons. The graph shows each piston's position, spread evenly through the turn. Axial piston pumps and motors in hydraulics Car air-conditioning compressors Helicopter rotor heads, where a swashplate sets the blade angles A helicopter rotor uses a swashplate in reverse: the pilot tilts a non-turning plate, and the turning plate above it changes each blade's angle as it goes round.","why":"Turn rotation into back-and-forth"},{"t":"m","u":"pages/reuleaux-triangle.html","n":"Reuleaux Triangle","c":"Curiosities","d":"A rounded triangle of constant width that turns inside a square, and can drill an almost square hole","k":"reuleaux triangle constant width square hole drill wankel rotor curve","w":"","o":null,"x":"Draw an equilateral triangle, then replace each side with an arc centred on the opposite corner. The result measures the same width in every direction, like a circle, even though it is not round. Because its width never changes, it can turn inside a square of that width while touching all four sides the whole time. Its corners sweep out almost the whole square: 98.77 % of it. Only four small curved slivers in the corners are left. Good to know: the centre does not stay still. It runs round a small, nearly round loop three times for every turn of the rotor, in the other direction. A drill made this way needs a floating chuck that lets the bit wander. Try it: switch between the rotor alone, the path of one corner, and the area it cuts. Drills and broaches for nearly square holes (Watts brothers' floating chuck) The rotor of a Wankel rotary engine, which is a close relative Coins, pencils and guitar picks that roll or feed smoothly The British 20p and 50p coins are Reuleaux heptagons: seven-sided curves of constant width, so coin machines can measure them across any direction and get the same answer.","why":""},{"t":"m","u":"pages/hoberman-ring.html","n":"Hoberman Ring","c":"Curiosities","d":"A ring of bent scissor bars that opens and closes like an iris, with every joint moving in a straight line","k":"hoberman sphere ring iris expanding scissor angulated deployable kinetic sculpture","w":"","o":null,"x":"Each unit is two identical bent bars, mirrored and pinned where they cross. The units are pinned end to end into a closed ring. Ordinary straight scissors cannot close into a ring and still expand. Bending each bar by 180° − 360°/N, where N is the number of units, makes every end joint slide straight in or out along a line from the centre. The whole ring has one degree of freedom: push any joint and all the others follow, so the opening grows evenly. Good to know: the hole in the middle changes far more than the outside does. That is what makes the same idea useful for irises, retractable roofs and expanding sculptures. Try it: change the number of units. More units give a rounder ring and a bigger opening compared with the size of the bars. The Hoberman sphere toy and expanding sculptures Retractable roofs and domes that open from the middle Kinetic art and stage sets that bloom open Chuck Hoberman's 11 m Hoberman Arch formed an expanding iris curtain over the stage at the 2002 Winter Olympics medals plaza in Salt Lake City.","why":""},{"t":"m","u":"pages/wobble-plate.html","n":"Wobble Plate","c":"Cams","d":"A tilted hub makes a plate wobble without turning, pushing a ring of pistons in and out in turn","k":"wobble plate nutating disc euler disk compressor axial piston swashplate","w":"","o":null,"x":"The shaft carries a hub set at an angle. A plate sits on the hub on a bearing, so the hub can turn inside it. A guide stops the plate turning. As the shaft turns, the high point of the tilt runs round the plate, so the plate wobbles while a mark on it stays in the same place. Each piston is joined to the plate by a rod with ball joints. As the wobble passes, each piston moves in and out once per turn of the shaft. Good to know: a swashplate looks the same but the plate turns with the shaft, so the pistons must slide on it through shoes. A wobble plate has no sliding at the plate face, only rocking joints, which suits pumps with lower speeds and simple lubrication. Try it: switch between wobble plate and swashplate and watch the red mark on the plate face. Car air-conditioning compressors Small axial piston pumps and air motors Kinetic sculptures where a ring of rods rises and falls in a wave Euler's Disk, the desk toy, is a wobble plate with no shaft: as the spinning disc settles, the point where it touches the table races round faster and faster while the disc itself hardly turns.","why":""},{"t":"m","u":"pages/oscillating-cylinder.html","n":"Oscillating Cylinder Engine","c":"Linkages","d":"A steam cylinder that swings on a pivot, so the piston rod can drive the crank directly and the swing works the valves","k":"oscillating cylinder wobbler steam engine trunnion mamod model engine","w":"","o":null,"x":"The piston rod is joined straight to the crank pin. Instead of a connecting rod that tilts, the whole cylinder tilts, swinging on a pivot called the trunnion. It is a slider-crank turned inside out: the slider (the cylinder) is pivoted, and the rod is fixed to the piston. The cylinder's port slides past two holes in a fixed block. Swinging one way lines it up with the steam inlet for the power stroke; swinging back lines it up with the exhaust. Good to know: the largest swing is sin⁻¹(r ÷ d), where r is the crank radius and d the distance to the trunnion. A longer distance gives a smaller swing, but a longer engine. Try it: change the trunnion distance and watch the swing angle and the port timing. Toy and model steam engines Early paddle steamers Kinetic toys and automata driven by air or steam In the 1840s, John Penn built large oscillating engines for Royal Navy paddle steamers: cylinders weighing several tonnes swung to and fro on their trunnions at every stroke.","why":""},{"t":"e","u":"elements/ball-bearing.html","n":"Ball Bearing","c":"Bearings","d":"Lets a shaft spin with very little friction while carrying a load","k":"bearing ball bearing race 608 skateboard radial thrust bushing","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":4,"x":"Two hardened rings with grooves (the inner and outer races), a row of steel balls between them, and a thin cage that keeps the balls evenly spaced. The inner race usually turns with the shaft and the outer race sits still in the housing. The balls roll instead of rub, which is far easier than sliding. The cage and balls orbit at a bit under half the shaft speed, while each ball spins on its own axis much faster. A deep-groove bearing like this carries mainly radial load (across the shaft) and some axial load (along it). The arrows show where the load passes through the balls. Good to know: bearing life is predicted with the L10 life formula. Halve the load and the bearing lasts about eight times longer. Try it: change the number and size of balls and the type of load. Work out a bearing's life in Do the math, and compare 45 other bearing types in the chart below the drawing. Skateboard, bicycle and car wheels Electric motors, fans and hard-disk drives Almost every machine with a turning shaft Precision bearing balls are among the roundest objects people make. The best grades are round to within about 0.08 thousandths of a millimetre, roughly a thousandth of the width of a human hair.","why":"Hold, locate or support parts"},{"t":"e","u":"elements/bolt-nut.html","n":"Bolt and Nut","c":"Fasteners","d":"Clamps parts together by stretching a bolt like a very stiff spring","k":"bolt nut screw fastener thread metric imperial torque preload washer m3 m4 m5 m6 m8","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":0,"x":"A bolt with a head and a threaded shank, a nut that runs on the thread, and the parts being clamped between them, often with washers. Turning the nut pulls the bolt and squeezes the parts. The bolt stretches a tiny amount, and that stretch is the clamp force, or preload, that holds the joint together. Most of the tightening torque is lost to friction in the threads and under the nut. Only about 10% of it actually stretches the bolt. Good to know: a properly tightened bolt hardly feels the load on the joint, because the clamped parts carry it. Loose bolts are the ones that break from fatigue. Try it: choose a size from M2 to M20 and a tightening torque and watch the clamp force. The Standard dimensions table lists the pitch, hex size, clearance hole and tap drill for each size, and Do the math shows the stress compared with the bolt's strength class. Steel structures and bridges Engines, wheels and machinery Furniture and bicycles Before 1841 every workshop cut threads its own way, so nuts and bolts from different makers would not fit. Joseph Whitworth's proposal that year became the first national screw-thread standard.","why":"Hold, locate or support parts"},{"t":"e","u":"elements/screw-types.html","n":"Screws and Drives","c":"Fasteners","d":"How screw heads, drive shapes and thread types are chosen","k":"screw phillips torx hex allen drive wood machine self tapping","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":1,"x":"A screw has a head (the part you see), a drive (the shape the tool fits into) and a thread. Machine screws have a fine, even thread that goes into a nut or a tapped hole. Wood screws have a coarse, sharp thread and a point that cuts its own way. Each turn moves the screw in by one lead. The thread is a ramp wrapped round a cylinder, turning a twist into a strong pull. Drives differ in how well they grip. Slotted bits slip out sideways; Phillips bits tend to push out (cam out) under high torque; square and Torx drives grip much better. Heads: pan heads sit on the surface, countersunk (flat) heads sit flush in a cone-shaped hole, socket caps fit in counterbored holes, and hex heads take a spanner. Try it: switch the drive, head and thread and watch the screw go in. Do the math works out turns and driving time. Furniture, electronics and appliances Woodwork and building Anywhere a part might need to come apart again Nature got there first: in 2011 scientists found that a weevil from New Guinea, Trigonopterus oblongus, has hip joints that are a real screw and nut, with the leg screwing into its socket.","why":"Hold, locate or support parts"},{"t":"e","u":"elements/spring.html","n":"Compression Spring","c":"Springs","d":"Stores energy and pushes back in proportion to how far it is squashed","k":"spring compression extension rate stiffness coil wire","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":5,"x":"A helix of round wire. The ends are usually closed and ground flat so the spring stands square. Squash it by x and it pushes back with F = k × x. The constant k is the spring rate, in N/mm. The wire is actually twisted, not bent, as the spring compresses. Thicker wire makes a much stiffer spring; bigger coils or more coils make it softer. Good to know: a spring can only be compressed until the coils touch (solid height). Designers keep it well short of that so it does not take a permanent set. Try it: change the wire, coil size and number of coils and watch the stiffness and force change. Pens, car suspension and mattresses Valves, switches and latches Toys and launchers Robert Hooke first published his law of springs in 1676 as a scrambled anagram, \"ceiiinosssttuv\", to claim the idea before revealing it. Two years later he gave the answer: \"ut tensio, sic vis\" (as the extension, so the force).","why":"Hold, locate or support parts"},{"t":"e","u":"elements/shaft-key.html","n":"Shaft Key","c":"Shaft parts","d":"Locks a gear or pulley to a shaft so they turn together","k":"keyway key way woodruff feather spline set screw hub","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":2,"x":"A shaft with a slot (keyway) along it, a hub with a matching slot, and a small rectangular steel key that fits in both. When the shaft turns, it pushes the key sideways, and the key pushes the hub. The key is loaded across its middle like scissors (shear) and pressed on its sides (bearing). Key sizes come from standard tables based on the shaft diameter. The only free choice is usually the key length. Good to know: the key is made the weakest link on purpose. If something jams, it shears before the expensive shaft or gear breaks. Try it: change the shaft diameter and key length. Do the math checks the key against the torque. Motor shafts, pulleys and gears Pumps and gearboxes Lawnmower blades and boat propellers Outboard boat motors often hold the propeller on with a soft shear pin, a close relative of a key. If the propeller hits a rock, the cheap pin snaps and saves the gearbox.","why":"Hold, locate or support parts"},{"t":"e","u":"elements/retaining-ring.html","n":"Retaining Ring","c":"Shaft parts","d":"A springy ring that snaps into a groove to hold parts in place","k":"circlip e-clip snap ring seeger groove","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":3,"x":"A flat split ring of spring steel with two lug holes, and a shallow groove on a shaft (external ring) or inside a hole (internal ring). Pliers in the lug holes stretch an external ring open, or squeeze an internal ring closed, so it can slide to the groove. Let go and it springs into the groove. The part of the ring sticking out of the groove makes a shoulder that stops a bearing or gear sliding along. Good to know: they replace nuts, threads and machined shoulders, which saves space and cost. They are usually called circlips. Try it: switch between an external and internal ring and pick a shaft size. Do the math gives typical groove sizes. Holding bearings in motors and gearboxes Piston pins in engines Bicycle hubs, toys and appliances Retaining rings store a lot of spring energy when stretched. If the pliers slip, a ring can fly across the room, which is why mechanics wear safety glasses even for this small job.","why":"Hold, locate or support parts"},{"t":"e","u":"elements/timing-belt.html","n":"Timing Belt","c":"Transmission","d":"A toothed belt that drives without slipping and keeps shafts exactly in step","k":"timing belt gt2 htd stepper cog tooth belt","w":"Connect shafts that are far apart belt chain sprocket drive power transmission distance timing belt pulley drive connect two shafts","o":2,"x":"A belt with teeth moulded on the inside, reinforced with strong cords, running on pulleys with matching grooves. The teeth lock into the grooves, so the belt cannot slip. It moves one tooth pitch for each groove that passes. Ratio = driven teeth ÷ driver teeth, just like gears, but quiet, light and with no lubrication. Good to know: belt length must be a whole number of teeth, so the shaft distance is chosen to fit. Each pitch has its own tooth shape (GT2 for small 3D printers, HTD for heavier drives). Try it: change the tooth counts and the pitch. Do the math works out the belt length and the steps per millimetre for a 3D printer axis. 3D printers, plotters and laser cutters Car engine camshaft drives Sewing machines and office printers In many car engines, if the timing belt snaps the pistons and valves collide. Engineers call these \"interference engines\", which is why belts are replaced on a schedule.","why":"Connect shafts that are far apart"},{"t":"e","u":"elements/lead-screw.html","n":"Lead Screw","c":"Linear motion","d":"Turns rotation into slow, strong, precise straight-line motion","k":"lead screw leadscrew acme trapezoidal jack ball screw","w":"Lift or pull a load lift hoist winch crane block and tackle load weight raise lower pull mechanical advantage jack Allow one direction only, or hold a position one way lock hold brake backstop self locking prevent reverse back driving ratchet","o":1,"x":"A long threaded rod turned by a motor or handle, and a nut that cannot turn, often fixed to a sliding carriage. Each turn moves the nut by one lead (pitch × number of starts). The thread is a ramp, so a small turning force makes a large push. A gentle thread slope gives a big push and fine control; a steep one gives speed. Good to know: with a gentle slope, friction stops the load from turning the screw backwards. The screw holds its position without a brake (self-locking). Ball screws use rolling balls to cut friction when efficiency matters more. Try it: change the pitch and number of starts and watch how far the carriage moves each turn. Do the math gives speed, torque and efficiency. Vices, clamps and car jacks 3D printer Z axes and CNC machines Adjustable desks and camera sliders Johannes Gutenberg built his printing press around 1440 by adapting the screw presses that were already used to squeeze grapes and olives.","why":"Lift or pull a load · Allow one direction only, or hold a position"},{"t":"f","u":"fabrication/tab-and-slot.html","n":"Tab and Slot","c":"Joining","d":"A tab on one flat part passes through a slot in another and holds it square, with no fastener","k":"tab slot t-slot flat pack laser cut box joint fit kerf Laser cutting CNC fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":0,"x":"One part has a tab sticking out of its edge. The other has a slot cut through it, the same width as the first part is thick. Push the tab through the slot and the two parts lock at a fixed angle, usually 90°. A laser burns away a thin line of material called the kerf, so every cut comes out a little wider than the line you drew. Slots end up bigger and tabs end up smaller. To get a snug fit, draw the slot narrower than the sheet by about the kerf. Good to know: the fit you want depends on the job. A press fit holds without glue but can crack brittle acrylic. A sliding fit goes together by hand but needs a dab of glue, a screw or a pin to stay put. Try it: change the kerf and the slot width below and watch the gap in the magnified view. Real fits depend on the material, so always cut a small test strip first. Flat-pack boxes, enclosures and furniture Laser-cut chassis and frames for robots and kinetic pieces Stacked slice-form models and kits Tab-and-slot lets a flat sheet become a three-dimensional object, which is why so many laser-cut boxes, kits and models are built this way.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/finger-joint.html","n":"Finger Joint","c":"Joining","d":"Interleaved fingers on two boards make a strong right-angle corner with plenty of glue area","k":"box joint finger joint comb joint corner drawer Laser cutting CNC fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":1,"x":"Both boards have rectangular fingers along the joining edge, with gaps between. The fingers of one board fit into the gaps of the other, so the boards meet at 90° and the corner locks together. The fingers stop the boards sliding sideways, and every finger adds surface for glue. That makes the joint much stronger than two plain edges stuck together. Good to know: use an odd number of fingers so the two boards have fingers on the outside edges and the ends line up. Fingers about one to three times the sheet thickness wide work well. Try it: change the number of fingers and the thickness. The kerf makes fingers a little narrower and gaps a little wider, so draw the fingers slightly wider than the gaps if you want it snug. Laser-cut and woodworking boxes and drawers Enclosures for electronics Cases for motors and gearboxes Finger joints are also called box joints, and they were cut by hand for centuries before routers and laser cutters made them quick.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/captive-nut.html","n":"Captive Nut Slot","c":"Joining","d":"A pocket that traps a nut so you can tighten a bolt from one side without holding the nut","k":"nut trap nut slot hex pocket t-nut bolt hold nut m3 m4 m5 Laser cutting 3D printing CNC fabrication technique design for assembly manufacturing dfm dfa","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":7,"x":"A hexagonal or square pocket is cut beside the bolt hole, and a nut is dropped or slid into it. The nut cannot turn, so the bolt can be tightened from the other side with one tool. In laser-cut sheet the pocket is a slot open to an edge. The nut slides in from the side, and a layer above or below holds it in place. In a 3D print it is a hexagonal pocket printed into the part. Good to know: make the pocket a little larger than the nut so it goes in easily, but not so large that the nut spins. Add a few tenths of a millimetre across the flats, and check with a test piece. Try it: pick a bolt size. The table lists the nut across flats and thickness for each size, and the drawing shows the pocket sized from them. Laser-cut layered frames bolted together Printed parts that need a strong, reusable thread Mounts for motors, bearings and sensors A captive nut gives a metal thread inside plastic or wood without any special inserts, and it can be undone and redone as often as you like.","why":"Hold, locate or support parts"},{"t":"f","u":"fabrication/heat-set-insert.html","n":"Heat-Set Insert","c":"Joining","d":"A brass threaded insert melted into a plastic part gives it a strong, reusable metal thread","k":"heat set insert threaded insert melt in brass insert soldering iron m3 m4 m5 thread plastic 3D printing fabrication technique design for assembly manufacturing dfm dfa","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":6,"x":"A brass insert with a knurled (ridged) outside is pushed into a slightly undersized hole while hot. A soldering iron melts the plastic around it, the plastic flows into the knurls and the insert sets as it cools. The result is a real metal thread. It survives many screw-ins and holds far more than a thread printed or tapped into plastic. Good to know: the hole should be a little smaller than the insert and deeper than its length, so melted plastic has somewhere to go. Press it in straight, stop when it sits flush and let it cool before using it. Try it: pick a thread size. The drawing shows the insert, the hole and the displaced plastic. The table lists typical hole sizes, which you should check against your own insert and filament. Printed enclosures with removable lids Mounting plates for motors and electronics Any printed part that needs to be assembled more than once The iron tip is usually set just above the printing temperature of the plastic, so it softens the plastic without making it run everywhere.","why":"Hold, locate or support parts"},{"t":"f","u":"fabrication/press-fit.html","n":"Press Fit","c":"Joining","d":"A part slightly bigger than its hole is pushed in, and friction holds it with no fastener","k":"press fit interference fit friction fit dowel pin bearing seat shaft hole tolerance Laser cutting 3D printing CNC fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":3,"x":"The pin or shaft is made a little larger than the hole. The difference is called interference. Pushing the part in stretches the hole and squeezes the pin, and the springback grips them together. Friction does the holding, so the amount of interference is critical. Too little and the part spins or falls out. Too much and the part cracks or will not go in at all. Good to know: stiff, brittle materials like acrylic tolerate very little interference. Softer or more elastic materials like many printed plastics and wood tolerate more. Metal-on-metal press fits are held to tight, standardised tolerances. Try it: change the interference and the material. The drawing shows the squeeze, and the meter shows whether it is likely to slip, hold or crack. Bearings and bushings pressed into housings Dowel pins and locating pins Gears and wheels pressed onto shafts Some machines are assembled by heating the outer part so it expands, dropping the inner part in, and letting it shrink tight as it cools.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/snap-fit.html","n":"Snap Fit","c":"Joining","d":"A flexible hook bends past a catch and springs back, locking two parts with no screws","k":"snap fit cantilever hook clip latch catch click 3D printing fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":2,"x":"A thin beam with a hook on the end is pushed against a ramp. The beam bends out of the way, the hook slides over the catch and the beam springs back, locking the parts together. The beam is bent every time it snaps in, so the plastic must stay within its elastic range or it will crack or take a permanent bend. The strain in the root of the beam depends on its thickness, how far it deflects and how long it is. Good to know: a longer, thinner beam bends with less strain. A rounded root (a fillet) spreads the stress. In 3D printing, print the beam so the layers run along its length, never across it. Try it: lengthen the beam or lower the hook, and watch the strain meter. If it passes the limit for the material, the hook will fail. Battery covers and toy casings Clips, buckles and lids Printed enclosures that open without tools A snap-fit hook gets its holding power from the angle of its back face. A steep back face is permanent, and a gentle one lets you release it.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/living-hinge.html","n":"Living Hinge","c":"Joining","d":"A thin, flexible strip of the same material acts as a hinge, with no pin and no extra parts","k":"living hinge flexure flex hinge bending kerf bend lattice 3D printing Laser cutting fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":4,"x":"A hinge made from the part itself: two rigid panels joined by a thin strip of material that bends. There is no pin and nothing to assemble. The thin strip bends over a small length, so the strain in it depends on its thickness and how tightly it folds. Thinner strips and larger bend radii survive more folds. Good to know: in plastics such as polypropylene a very thin, moulded strip can fold thousands of times. In a 3D print or in cut wood, a hinge is more limited. Try it: change the strip thickness and bend angle. The strain meter shows how hard the strip is working. Lids on food containers and boxes Flip-top bottle caps Laser-cut curved panels and flexible joints The lid of a ketchup or shampoo bottle often hangs on a thin moulded plastic strip like this, and it keeps flexing open and shut every time you use it.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/laser-kerf.html","n":"Laser Kerf and Fit","c":"Designing for the process","d":"The laser burns a thin line away, so parts come out smaller and holes bigger than you drew","k":"kerf laser cutter tolerance offset compensation fit clearance beam width Laser cutting fabrication technique design for assembly manufacturing dfm dfa","w":"Make a part that comes out right tolerance fit kerf clearance overhang dfm dfa design for manufacturing laser 3d print cnc corners mistake proof","o":0,"x":"A laser cuts by burning a narrow channel along your line. The channel is the kerf. It is typically a tenth to a third of a millimetre wide, depending on the machine, the lens and the material. The material that was burned away comes from both sides of the line: outside edges of parts shrink by half the kerf and the edges of holes grow by half the kerf. Good to know: you can correct for it by drawing parts bigger and holes smaller by the kerf, or by offsetting the cut line in your software. Measure your own kerf by cutting a row of slots and checking the width. Try it: slide the kerf and watch the part come out smaller than the drawn outline. The table shows how to correct each size. Any laser-cut part that has to fit another part Gears and cams that must mesh accurately Tab-and-slot and finger joints Kerf is an old sawmill word for the cut a saw leaves behind. The same idea applies to a saw, a router, a waterjet or a laser.","why":"Make a part that comes out right"},{"t":"f","u":"fabrication/print-tolerances.html","n":"Printing Tolerances and Overhangs","c":"Designing for the process","d":"Printed holes come out small, and steep overhangs sag, so design to what the printer can do","k":"fdm 3d print tolerance overhang bridging support hole shrink wall thickness layer nozzle 3D printing fabrication technique design for assembly manufacturing dfm dfa","w":"Make a part that comes out right tolerance fit kerf clearance overhang dfm dfa design for manufacturing laser 3d print cnc corners mistake proof","o":1,"x":"A 3D printer builds a part in layers, each laid on the one below. A hole is made from layers of plastic pushed around a circle, and the plastic tends to bulge inward, so holes come out a little smaller than designed. Each layer must sit on the layer below. A gentle overhang is supported by the layer under it, but a steep overhang has nothing underneath, so the plastic sags. About 45° from vertical is the usual safe limit. Good to know: for a hole that a pin or bolt must pass through, make the hole bigger than the pin by a tenth to a third of a millimetre. Check with a quick test print of a few hole sizes before the real job. Try it: raise the overhang angle and watch the layers lose their support. Change the nozzle size to see the thinnest wall you can print. Printed housings with bolt holes Brackets and mounts that bolt to other things Parts that must print without supports Many printers can bridge a short flat gap in mid-air. The plastic is stretched across it like a rope and sags a little in the middle.","why":"Make a part that comes out right"},{"t":"f","u":"fabrication/cnc-corners.html","n":"Inside Corners and Dog-Bones","c":"Designing for the process","d":"A round cutter cannot make a sharp inside corner, so square parts need a relief cut to fit","k":"dog bone dogbone t-bone inside corner fillet router end mill cutter radius pocket CNC Laser cutting fabrication technique design for assembly manufacturing dfm dfa","w":"Make a part that comes out right tolerance fit kerf clearance overhang dfm dfa design for manufacturing laser 3d print cnc corners mistake proof","o":2,"x":"A router or end mill is round, so it can never cut a perfectly sharp inside corner. It leaves a rounded corner with the radius of the cutter. When a square-cornered part must fit into that pocket, its corner hits the rounded fillet and will not go in. The cutter has to remove a little extra in the corner. Good to know: a dog-bone relief cuts a small circle into each corner so the square part fits. A T-bone does the same along the edge. Or you can round the corners of the part to match the cutter radius. Try it: change the cutter diameter and the corner style, and watch the tool path. A smaller cutter leaves a smaller radius but takes much longer. CNC-routed plywood and furniture Machined pockets for fitting parts Even laser-cut slots, where the beam leaves a tiny radius and burn The dog-bone gets its name from the shape of the slot ends, which look like the ends of a bone.","why":"Make a part that comes out right"},{"t":"f","u":"fabrication/poka-yoke.html","n":"One-Way Assembly","c":"Designing for assembly","d":"Add an asymmetric feature so a part can only go together the right way round","k":"poka yoke mistake proofing asymmetric keyed orientation assembly dfa design for assembly Laser cutting 3D printing CNC fabrication technique design for assembly manufacturing dfm dfa","w":"Make a part that comes out right tolerance fit kerf clearance overhang dfm dfa design for manufacturing laser 3d print cnc corners mistake proof","o":3,"x":"If a part can be assembled two ways and only one is right, someone will eventually get it wrong. A small asymmetric feature, such as an offset hole, a notch or a chamfered corner, makes the wrong way physically impossible. The idea comes from manufacturing, where it is called poka-yoke, a Japanese term for mistake-proofing. The part stops the mistake instead of relying on the person to notice. Good to know: the cheapest asymmetry is one that costs nothing to make, like moving a hole off centre. Make the difference big enough to see and feel, because a tiny offset invites forcing it. Try it: watch the part try the wrong way round and stop, then the right way. Change how far the odd peg sits off the line to see how clear the difference is. Connectors and plugs shaped so they cannot be reversed Kits where the parts are cut flat and assembled by hand Batteries, SIM cards and memory cards with a cut corner The cut corner on a SIM card and on many memory cards is the same trick: it only fits one way round.","why":"Make a part that comes out right"},{"t":"f","u":"fabrication/tapped-hole.html","n":"Tapped Holes and Tap Drills","c":"Holes and threads","d":"Cut a thread straight into a part so a screw goes in without a nut","k":"tap tapping tap drill thread hole metric unc unf m3 m4 m5 m6 m8 thread engagement helicoil Machining CNC 3D printing fabrication technique design for assembly manufacturing dfm dfa","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":8,"x":"First drill a hole a little smaller than the screw: the tap drill. Then a tap, a hardened screw with cutting edges, is turned into the hole and cuts the thread into its wall. The tap drill sets how deep the thread is. For metric coarse threads, the screw size minus the pitch gives about 75 % thread depth, which is plenty: deeper threads are barely stronger but much harder to tap. How much thread you need depends on the material. In steel, a length of one screw diameter is as strong as the screw. Softer aluminium needs about 1.5 to 2 diameters, and plastics about 2 to 2.5. Good to know: in a blind hole (one with a bottom), drill deeper than the thread, because the tap's tip is tapered and cannot cut full thread right to the bottom. Turn a hand tap back a quarter turn every turn or so to break the chip, and use cutting oil in metal. Try it: pick a screw size and the material. The drawing shows the tap drill, the thread depth you need and how deep to drill. Machined brackets, plates and housings Printed parts where a screw goes in only a few times (tap the plastic, or use a heat-set insert for more) Repairs: re-tapping damaged threads, or drilling out and tapping one size bigger The 75 % rule is a real trade-off: a full 100 % thread is only about 5 % stronger than a 75 % one, but takes roughly three times the torque to tap and breaks far more taps.","why":"Hold, locate or support parts"},{"t":"f","u":"fabrication/countersink-counterbore.html","n":"Countersinks and Counterbores","c":"Holes and threads","d":"Sink a screw head below the surface: a cone for flat heads, a stepped pocket for cap screws","k":"countersink counterbore flat head socket head cap screw flush recess spot face Machining CNC 3D printing fabrication technique design for assembly manufacturing dfm dfa","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":9,"x":"A countersink is a cone cut at the top of a clearance hole, so a flat (countersunk) screw head sits flush. Metric countersunk screws have a 90° head; most inch flat-head screws have 82°. A counterbore is a flat-bottomed pocket, wider than the head and a little deeper, so a socket head cap screw sits below the surface with its full head bearing on a flat seat. A countersunk head also centres the part on the screw, which locates it. A counterbore leaves room to slide the part a little before tightening, which helps when holes do not quite line up. Good to know: a countersunk head in thin sheet can pull through, because the cone leaves little material. If the sheet is thinner than the head is tall, use a counterbore, a pan head or a dimpled hole instead. Try it: pick the screw size and head type. The section shows the hole, the seat and the screw going in, with the sizes to draw. Flush faces on jigs, fixtures and sliding parts Machine frames and aluminium extrusion brackets Printed and CNC-cut enclosures where screws must not snag Inch flat-head screws use 82° and metric ones use 90°. Put one in the other's countersink and the head touches only on a thin ring, so it never sits flush and can work loose.","why":"Hold, locate or support parts"},{"t":"f","u":"fabrication/blind-rivet.html","n":"Blind (Pop) Rivets","c":"Joining","d":"A tube with a nail through it that you set from one side to clamp sheets together for good","k":"pop rivet blind rivet rivnut rivet nut sheet metal Sheet metal Laser cutting CNC fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":9,"x":"A blind rivet is a hollow body with a head, and a steel pin (the mandrel) through it with a ball on the far end. It goes through holes in both sheets from one side. A rivet tool grips the mandrel and pulls. The ball squashes the far end of the body into a fat bulb, clamping the sheets between the bulb and the head. When the clamp is tight the mandrel snaps off. Each length of rivet suits a range of total thickness, its grip range. Too short and the bulb cannot form; too long and it forms loosely. Good to know: drill the hole about 0.1 mm bigger than the rivet. Keep rivets at least two diameters from an edge and about three to four diameters apart. Rivets carry load best across the joint (in shear), not pulling the sheets apart. Try it: pick the rivet size and the thickness of the sheets. The panel gives the drill size, spacing and a rough grip check. Sheet metal ducts, enclosures and trailers Joining aluminium to plastic or composite panels Repairs where you can reach only one side Blind rivets were developed in the 1930s for building aircraft, where the inside of a wing or fuselage skin often cannot be reached.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/wood-inserts.html","n":"Threaded Inserts in Wood","c":"Holes and threads","d":"Metal threads set into wood or plywood so bolts can go in and out many times","k":"threaded insert wood t-nut tee nut cross dowel barrel nut furniture bolt Woodworking CNC Laser cutting fabrication technique design for assembly manufacturing dfm dfa","w":"Hold, locate or support parts fastener bolt nut screw shaft key retaining ring circlip bearing spring hardware hold together mount","o":10,"x":"Screws in wood work once or twice; then the wood fibres wear out. A metal insert gives a machine thread (M6, 1/4-20 and so on) that lasts. Screw-in inserts have a coarse outer thread that cuts into the wood and a machine thread inside. T-nuts are hammered in from the back, with prongs to stop them turning. Cross dowels (barrel nuts) sit in a hole across the board for flat-pack corners. Each type needs the hole size the maker gives. Too small and the wood splits; too big and the insert pulls out. Hardwood usually wants a slightly bigger hole than softwood. Good to know: keep inserts away from edges (at least one and a half insert diameters), drive them dead straight with a bolt and a nut locked on it, and put a drop of epoxy on them in soft wood or plywood edges. Try it: pick the type. The drawing shows how it holds, and the panel lists typical hole sizes. Flat-pack and knock-down furniture Jigs and workshop fixtures that are taken apart Laser-cut plywood enclosures and stands Old wooden bed frames were held together with bed bolts: a long bolt through the post into a nut set in a hole across the rail. Flat-pack cross dowels are the same idea.","why":"Hold, locate or support parts"},{"t":"f","u":"fabrication/dowel-joint.html","n":"Dowel Joint","c":"Joining","d":"Round pins in matching holes line two parts up and make a glued joint stronger","k":"dowel pin locating pin alignment joinery Woodworking CNC 3D printing fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":6,"x":"Holes are drilled in both parts at exactly matching places, and short round pins, the dowels, are glued into them. The dowels line the parts up and carry load across the joint. For wood, a dowel about a third to half the board thickness works well, set about halfway into each part. Fluted or spiral dowels let glue and trapped air escape. The holes must match closely. Use a dowel jig, or drill one part and mark the other with dowel centres. Drill each hole 1 to 2 mm deeper than half the dowel so it does not bottom out. Good to know: in 3D prints and laser-cut parts, dowel pins (hard steel pins) are a cheap, very accurate way to locate parts. Make one hole a snug fit and the other a slip fit or a slot, so the parts still go together if the spacing is slightly off. Try it: change the board thickness. The drawing sizes the dowels and holes from it. Cabinet and furniture joints Locating machined or printed parts exactly, then bolting them Jigs and fixtures that must go back in the same place Machinists say \"two pins, not three\": two dowel pins fix a part completely in a plane. A third pin can never be drilled perfectly in line, so it only makes the parts fight.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/cross-halving.html","n":"Cross-Halving (Slot-Together) Joint","c":"Joining","d":"Two parts, each slotted halfway, slide together into a cross with no fasteners","k":"cross halving halving joint egg crate slot together interlocking Laser cutting CNC Woodworking fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":5,"x":"Each part has a slot as wide as the other part is thick, cut halfway through its height. One slot opens from the top, the other from the bottom, and the parts slide together into a +. Repeat it and you get an egg-crate: a grid of slotted strips that is light, stiff and goes together by hand. The slot width sets the fit. Allow for kerf on a laser, and for a round cutter on a router (add dog-bones at the slot bottom). Good to know: add a small chamfer or lead-in at the open end so parts start easily, and make the slots a hair deeper than half so the tops and bottoms line up flush. Try it: change the sheet thickness and the fit. The drawing shows the gap or squeeze in each slot. Egg-crate dividers, shelves and lightweight frames Laser-cut models, lamps and furniture Internal stiffening ribs in boxes and wings Many flat-pack cardboard displays and laser-cut animal skeleton kits are made almost entirely from cross-halving joints.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/dovetail.html","n":"Dovetail Joint","c":"Joining","d":"Flared tails lock into matching pins so the joint cannot be pulled apart in one direction","k":"dovetail sliding dovetail joinery tails pins Woodworking CNC 3D printing fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":7,"x":"One board has tails, flared like a dove's tail. The other has pins between sockets of the same shape. The tails slide in from one side only. Pulling the tail board straight out is blocked by the flare, so the joint holds even before the glue sets. The usual slope is 1 in 6 for softwood and 1 in 8 for hardwood (about 9.5° and 7°). Steeper slopes look bolder but can split the short grain at the corners. Good to know: a sliding dovetail (a long dovetail groove) is a strong way to fit a shelf, or a rail on a 3D print. For prints, leave about 0.2 to 0.3 mm of clearance each side and print the rail lying down so its layers are strong. Try it: change the slope and the number of tails. Drawer fronts, boxes and fine furniture Sliding dovetail rails and mounts on printed and machined parts Machine slides: lathe and mill ways are dovetails The cross-slide and compound of most lathes run on dovetail ways, the same shape a cabinetmaker cuts by hand.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/glue-joints.html","n":"Glue Joints","c":"Joining","d":"Design the joint so the glue is sheared over a big area, never peeled from one edge","k":"glue adhesive epoxy pva super glue cyanoacrylate solvent weld acrylic bond lap joint Woodworking Laser cutting 3D printing CNC fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":8,"x":"Glue is strong when it is sheared: two surfaces sliding past each other with the glue in between. It is weak when it is peeled or split open from one edge, because then only a thin line of glue carries the load. So make overlaps, tabs and fingers that turn the load into shear and give the glue more area. A butt joint (end against end) has the least area and peels easily. Choose the glue for the materials: PVA for wood, solvent cement for acrylic, cyanoacrylate (super glue) for small hard parts, and epoxy for mixed materials and gaps. Good to know: end grain in wood soaks up glue and holds poorly. Polyethylene and polypropylene barely bond with anything, so use fasteners or special primers. Clean, slightly roughened surfaces always bond better. Try it: switch the joint type and the load. The meter shows how hard the same load is on the glue. Furniture, boxes and laser-cut assemblies Acrylic displays and enclosures (solvent-welded) Printed parts too big for the printer, joined in sections A well-glued long-grain wood joint is usually stronger than the wood itself: test it to failure and the wood next to the glue line breaks first.","why":"Join parts without bought fasteners"},{"t":"f","u":"fabrication/sheet-metal-bend.html","n":"Sheet Metal Bends","c":"Designing for the process","d":"Work out the flat size before bending, and keep holes and edges where the bend cannot tear them","k":"sheet metal bend allowance k factor bend deduction press brake flange relief Sheet metal Laser cutting fabrication technique design for assembly manufacturing dfm dfa","w":"Make a part that comes out right tolerance fit kerf clearance overhang dfm dfa design for manufacturing laser 3d print cnc corners mistake proof","o":4,"x":"When sheet bends, the outside stretches and the inside squashes. Somewhere in between, a line called the neutral axis keeps its length. The flat blank is measured along that line. The neutral axis sits a fraction K of the thickness in from the inside, the K-factor. For air bending most metals, K is about 0.33 to 0.5. The length used up by a bend, the bend allowance, is angle × (R + K × T). Bend most metals with an inside radius about equal to the thickness. Much tighter, and harder metals crack on the outside. Good to know: keep holes at least about 2.5 × T plus the radius away from a bend, or they stretch into ovals. Where a bend stops partway along an edge, cut a small relief slot (about T wide, R + T deep) so the metal does not tear. Try it: change the thickness, the radius and the angle. The calculator gives the bend allowance and the flat length. Brackets, enclosures and chassis cut on a laser or punch and then bent Motor mounts and robot frames Ducts, panels and furniture Sheet metal shops keep their own K-factor tables for each material, thickness and tool, because the same part bent on two different press brakes can come out a few tenths of a millimetre different.","why":"Make a part that comes out right"},{"t":"f","u":"fabrication/flexure-hinge.html","n":"Flexure Hinges","c":"Designing for the process","d":"A thin, springy section bends instead of a pin turning, with no play, wear or friction","k":"flexure compliant mechanism flex hinge notch leaf spring strain 3D printing CNC Laser cutting fabrication technique design for assembly manufacturing dfm dfa","w":"Make a part that comes out right tolerance fit kerf clearance overhang dfm dfa design for manufacturing laser 3d print cnc corners mistake proof","o":5,"x":"A flexure is a thin strip or neck in an otherwise stiff part. Push on the part and the thin part bends like a spring, so the part moves as if it were on a hinge. The strip is safe as long as the strain (the stretch of its outer surface) stays below what the material can take. For a strip of length L and thickness t bent through an angle θ, the surface strain is t × θ ÷ (2L). So thinner and longer flexures bend further. Halve the thickness and the strip can bend twice as far, but it also gets much floppier and weaker. Good to know: flexures have no play and no friction, which makes them great for precise, small motions. Keep the strain to half the material's limit if it will flex many times, and print the strip so it bends across the layers, not between them. Try it: change the thickness, length and material. The colour shows the strain; red means it will crack or bend for good. Precision stages and instrument mounts Compliant grippers, clips and toys made in one piece Bistable switches and snap mechanisms Some telescope mirror mounts and watch parts use flexures because the motion must be exact to a few micrometres, and any play in a pin would be too much.","why":"Make a part that comes out right"},{"t":"f","u":"fabrication/magnets.html","n":"Magnets for Alignment and Closure","c":"Joining","d":"Small neodymium magnets in pockets hold lids shut and pull parts into place","k":"magnet neodymium ndfeb magnetic lid closure pocket 3D printing Laser cutting CNC fabrication technique design for assembly manufacturing dfm dfa","w":"Join parts without bought fasteners join joint connect assemble flat pack no screws glue snap click lock fit tab slot box joint dfa","o":10,"x":"A small neodymium (NdFeB) disc magnet is pressed or glued into a pocket in each part. When the parts come close, the magnets pull them together and line them up. The pull falls off very fast with distance. Even a thin wall or paint layer between two magnets cuts the force noticeably, so set the magnets as close to the surface as you can. Polarity matters: if one magnet is flipped, the parts push apart. Mark the facing side of each magnet before gluing, or alternate the poles so the parts only fit one way round. Good to know: neodymium is brittle and loses strength above about 80 °C for the common N grades, so do not hammer it in or heat it with a soldering iron. Printed pockets come out small, so add about 0.2 mm to the diameter. Try it: change the gap between the magnets and watch the pull drop. Lids and doors on boxes and enclosures Self-aligning modular parts and display stands Tool holders, covers and quick-release mounts Neodymium magnets were invented in 1982 and are now in almost every phone speaker, hard drive and electric car motor.","why":"Join parts without bought fasteners"},{"t":"k","u":"machining/manual-mill.html","n":"Manual Milling Machine","c":"Manual machines","d":"A spinning cutter stays put while the work, clamped to a moving table, is fed into it","k":"milling machine bridgeport knee mill end mill vise tram edge finder dro quill","w":"","o":null,"x":"The cutter (an end mill, drill or face mill) spins in the spindle. The work is clamped in a vise on the table, which moves left-right (X) and in-out (Y) with handwheels; the knee or quill moves up and down (Z). You set the depth, then wind the table so the cutter takes a thin layer off the side or face. Dials on the handwheels, or a digital readout (DRO), show the position to 0.01 mm or 0.0005 inch. The spindle speed comes from the cutting speed of the material and the cutter diameter: rpm = 1000 × cutting speed (m/min) ÷ (π × diameter in mm). Bigger cutters and harder metals turn slower. Good to know: on most manual mills, feed conventionally (against the cutter rotation). Climb milling gives a better finish but can pull the table into the cutter through the leadscrew backlash. Try it: change the cutter diameter and the material. The readout gives a starting speed and feed for that cutter. Flat faces, steps, slots and pockets Accurately placed holes: drilling, reaming and boring One-off parts, fixtures and repairs where programming a CNC is not worth it The \"Bridgeport\" knee mill, first made in 1938, became so common that machinists still call almost any small vertical knee mill a Bridgeport.","why":""},{"t":"k","u":"machining/manual-lathe.html","n":"Manual Lathe","c":"Manual machines","d":"The work spins and a still cutting tool is fed along it to make round parts","k":"lathe turning facing chuck tailstock tool post threading parting knurling","w":"","o":null,"x":"The work is held in a chuck on the headstock spindle and spins. A single-point cutting tool sits in a tool post on the carriage, which slides along the bed (Z). The cross-slide moves the tool in and out (X). Moving the tool along the work turns a diameter. Moving it across the end faces it. Drills and reamers go in the tailstock for holes on the centre line. The spindle speed comes from the cutting speed and the work diameter, so a big diameter turns slowly. The feed is set per turn of the spindle (mm per rev) with the gearbox, and the lead screw also cuts threads. Good to know: set the tool tip exactly at centre height, or it rubs on the face and leaves a pip in the middle. Support long, thin work with the tailstock centre: unsupported stick-out more than about three diameters chatters and bends. Try it: change the diameter and the material. Notice how the rpm falls as the diameter grows. Shafts, pins, spacers, bushings and pulleys Threads, tapers and grooves Facing and boring flat, square faces and accurate holes Henry Maudslay's screw-cutting lathe of around 1800 let workshops copy accurate screws for the first time, which is why he is often called the father of the machine tool industry.","why":""},{"t":"k","u":"machining/cnc-mill.html","n":"CNC Mill","c":"CNC machines","d":"A computer drives all the axes from a program, so complex shapes and repeat parts come out the same every time","k":"cnc mill machining center vmc g-code cam toolpath adaptive work offset g54 probe fusion","w":"","o":null,"x":"A CNC mill is a milling machine whose axes are driven by motors with ball screws, following a program of G-code. CAM software turns your 3D model into toolpaths and then into G-code. Before running, the machinist sets the work offset (where the part zero is, for example G54) and the tool length offsets, usually with a probe or tool setter. Modern toolpaths keep the load on the cutter even. Adaptive (high-efficiency) clearing takes a narrow radial cut, about 8 to 20 % of the cutter diameter, at full flute depth and a high feed. Chips stay thick, heat goes out with the chips and tools last longer. Good to know: with a narrow radial cut the chip comes out thinner than the feed per tooth (chip thinning). Raise the feed to make up for it, or the cutter rubs and wears fast. Air blast or coolant must clear the chips, or the cutter re-cuts them. Try it: change the radial engagement. The calculator raises the feed to keep the real chip thickness on target. Production runs and parts with 3D surfaces Pockets, profiles, holes and threads in one setup Moulds, fixtures, enclosures and prototype parts The first numerically controlled milling machine was shown at MIT in 1952, reading its instructions from punched paper tape.","why":""},{"t":"k","u":"machining/cnc-router.html","n":"CNC Router","c":"CNC machines","d":"A fast spindle on a gantry cuts sheets of wood, plastic and aluminium from a drawing","k":"cnc router shapeoko onefinity spoilboard plywood tabs onion skin compression bit chip load","w":"","o":null,"x":"A router has a high-speed spindle (often 12,000 to 24,000 rpm) on a gantry that moves over a large, flat bed. It is lighter than a mill, so it suits sheets and soft materials. The sheet sits on a spoilboard, a sacrificial board the cutter can go slightly into. It is held with screws, clamps, tabs, double-sided tape or a vacuum table. Feeds come from the chip load: feed = rpm × flutes × chip load. Too slow and the bit rubs, makes dust instead of chips and can burn or catch fire. Good to know: cut parts free with small tabs or an onion skin (a thin layer left at the bottom) so they do not move on the last pass. Downcut and compression bits give clean faces on plywood; upcut bits clear chips better. Try it: change the bit, the spindle speed and the chip load. The readout gives the feed rate to set. Furniture, signs and plywood parts Plastic panels, enclosures and machine guards Aluminium plates, light engraving and moulds in foam If a router bit is fed too slowly in wood, the friction can heat chips enough to start a fire in the dust extraction, which is why router shops keep an extinguisher by the machine.","why":""},{"t":"k","u":"machining/laser-cutter.html","n":"Laser Cutter","c":"Sheet cutting","d":"A focused beam of light vaporises and burns a thin line through sheet material","k":"laser cutter co2 fiber glowforge xtool focus air assist engraving kerf","w":"","o":null,"x":"A CO2 laser tube makes an invisible infrared beam. Mirrors carry it to a head, where a lens focuses it to a tiny spot. The spot heats the material so fast that it melts, burns or vaporises. The head moves over the sheet following the drawing, cutting at full power for cut lines and lower power for engraving and scoring. The beam is narrowest at the focus and spreads above and below it, so the cut is slightly V-shaped. Focus near the surface for thin sheet, or a little into the material for thick acrylic and wood. Good to know: air assist blows the flame out and the smoke away, giving cleaner edges. Never cut PVC or vinyl (it releases chlorine gas that damages lungs and the machine), and never leave a running laser alone: it can set the work on fire. Try it: move the focus and change the thickness. Watch the kerf narrow or widen through the cut. Wood, plywood, MDF, acrylic, card, leather and fabric Engraving and marking Fibre lasers cut and mark metal; most hobby CO2 lasers cannot cut metal CO2 lasers are surprisingly efficient for a laser, and their 10.6 µm wavelength is absorbed well by wood and plastics but reflected by bare metal, which is why they engrave so well but struggle with metal.","why":""},{"t":"k","u":"machining/waterjet.html","n":"Waterjet Cutter","c":"Sheet cutting","d":"A needle-thin stream of water and sand at supersonic speed erodes through almost anything","k":"waterjet water jet abrasive garnet omax flow taper jet lag","w":"","o":null,"x":"A pump raises water to around 4,000 bar (60,000 psi). It shoots through a tiny jewel orifice, and abrasive garnet is drawn into the stream in a mixing tube. The jet wears away the material grain by grain. Because it cuts cold, there is no heat-affected zone: hardened steel stays hard, and plastics and composites do not melt. It cuts metal, stone, glass and rubber, up to 100 mm or more thick. The jet loses energy as it goes down through the material, so the bottom of the cut lags behind the top (jet lag) and the cut can taper. Machines slow down at corners and use quality settings to control this. Good to know: the kerf is wide (about 0.8 to 1 mm), and slow, high-quality settings take much longer. Brittle or layered materials need a gentle low-pressure pierce or a pre-drilled start hole. Try it: change the cutting speed. Faster cuts bend the jet more and leave a rougher, more tapered edge. Thick metal plates, tool steel, titanium and armour Stone, tile, glass and composites Rubber, gaskets and foam (with water only, no abrasive) A waterjet with no abrasive, just water, is used to cut cakes, frozen food and paper nappies, because it is clean and leaves no blade to wash.","why":""},{"t":"k","u":"machining/plasma-cutter.html","n":"Plasma Cutter","c":"Sheet cutting","d":"An electric arc through a jet of gas melts steel and blows it out of the cut","k":"plasma cutter cnc plasma dross amperage consumables torch height","w":"","o":null,"x":"The torch squeezes compressed air or gas through a small nozzle around an electrode. An electric arc jumps from the electrode to the work and turns the gas into plasma, hot enough to melt steel. The fast gas blows the molten metal out of the bottom, leaving a cut. The work must conduct electricity, so plasma cuts steel, stainless and aluminium, but not wood or plastic. Speed and cut height matter a lot. Too slow leaves globs of melted metal (dross) under the cut; too fast leaves a small hard bead and the arc lags and sprays sparks up. Good to know: plasma is fast and cheap for steel plate, but the edge is rougher and slightly bevelled, with a heat-affected zone. Size the machine by amperage: roughly, a 45 A torch cuts about 12 mm of mild steel well. Try it: change the cutting speed. Watch the arc lag and where the dross forms. Steel plate brackets, signs, art and trailers Cutting steel too thick for a hobby laser Repairs, scrap cutting and bevel prep for welding The plasma inside the arc is several times hotter than the surface of the Sun, but most of the cutting is done by the gas jet blowing the melt away.","why":""},{"t":"k","u":"machining/speeds-feeds.html","n":"Speeds and Feeds","c":"Reference","d":"How fast to spin the cutter and how fast to feed it, from the material and the tool","k":"speeds and feeds sfm surface speed rpm feed rate chip load chipload feed per tooth chip thinning mrr","w":"","o":null,"x":"Every material has a cutting speed: how fast the cutting edge can move through it, in metres per minute (or surface feet per minute). From it, rpm = 1000 × speed ÷ (π × diameter). The feed per tooth (chip load) is how thick a chip each cutting edge takes. Feed rate = rpm × number of teeth × feed per tooth. Too slow a feed rubs instead of cutting: heat, wear and a glazed surface. Too fast breaks tools. The right chip carries the heat away. Good to know: carbide tools run about three to four times faster than high-speed steel (HSS). Small, light machines cannot reach high rpm or take heavy cuts, so start at the low end and listen. Try it: change the material, tool and radial engagement. The cutter view shows how a narrow cut thins the chip. Setting a manual mill, lathe, CNC mill or router Checking CAM software suggestions Working out cycle time and how fast metal can be removed Frederick Taylor ran tens of thousands of cutting tests from 1880 to 1905 to find these relationships, and co-invented high-speed steel along the way.","why":""},{"t":"k","u":"machining/tolerances-fits.html","n":"Tolerances and Fits","c":"Reference","d":"How much a size may vary, and how to pick a hole and shaft that slide, locate or press together","k":"tolerance fit iso 286 h7 g6 k6 p6 clearance interference transition hole basis it grade","w":"","o":null,"x":"No part is made exactly to size. A tolerance says how far it may vary: 20 +0.021/0 means anything from 20.000 to 20.021 mm is good. ISO fits name a hole and a shaft tolerance together, for example H7/g6. Capital letters are holes, small letters shafts; the number is the grade (smaller is tighter). Choosing H7 for the hole and changing only the shaft letter gives everything from a sliding fit (g6) to a light press (k6) to a heavy press (s6). This \"hole basis\" system suits shops that ream holes to H7. Good to know: tighter tolerances cost more, sometimes a lot more. Put tight tolerances only on the faces that fit something; leave the rest to a general tolerance such as ISO 2768-m. Try it: pick the size and the fit. The bars show the hole and shaft zones and the clearance or squeeze. Bearing seats, dowel pins and shafts Sliding and rotating fits Telling a machine shop what you really need A fit of H7/h6 on a 20 mm shaft allows 0 to 0.034 mm of clearance: about half the thickness of a human hair.","why":""},{"t":"k","u":"machining/drawings-gdt.html","n":"Engineering Drawings and GD&T","c":"Reference","d":"How to read and make a drawing a machine shop can quote and make, including the main GD&T symbols","k":"engineering drawing gd&t gdt geometric dimensioning tolerancing datum position flatness mmc title block third angle first angle","w":"","o":null,"x":"A drawing shows the part in views (front, top, side), with dimensions, tolerances, material, finish and quantity in the title block. In the US, views are laid out in third-angle projection; much of Europe and Asia uses first-angle. The title block shows which. Geometric dimensioning and tolerancing (GD&T) controls shape and position, not just size: flatness, perpendicularity, position of a hole and so on. Each control sits in a feature control frame. Position tolerance gives a hole a round tolerance zone around its exact (basic) location, measured from datums: the faces that locate the part in its assembly. Good to know: at maximum material condition (MMC, the smallest hole), a hole that comes out bigger gets extra position tolerance, called bonus tolerance. It still fits the mating pin. Try it: change the hole size and the position tolerance. The drawing shows the zone and whether the hole passes. Getting parts quoted and made by a machine shop Inspecting parts that come back Talking clearly with other engineers GD&T grew out of work by Stanley Parker at a Scottish torpedo factory in the 1940s. He noticed that square tolerance zones for hole positions rejected parts that would fit perfectly, and proposed round ones.","why":""},{"t":"k","u":"machining/measuring.html","n":"Measuring Tools","c":"Reference","d":"Calipers, micrometers and indicators: how to read them and how far to trust them","k":"caliper vernier micrometer dial indicator measure inspection gauge","w":"","o":null,"x":"A vernier caliper has a main scale in millimetres and a sliding vernier scale. Read the whole millimetres where the vernier zero sits, then find the vernier line that lines up best with a main-scale line: that gives the hundredths. Micrometers measure to 0.01 mm (or 0.001 mm with a vernier) with a fine screw and a ratchet that sets the same light pressure each time. Dial and test indicators measure small movements, for setting up work in a vise or a chuck, and checking that faces are flat and square. Good to know: a tool is only good for parts about ten times looser than its accuracy. A caliper accurate to ±0.02 mm is fine for a ±0.2 mm tolerance, but use a micrometer for ±0.02 mm. Try it: change the reading and the scale. The magnified view shows which vernier line lines up. Checking parts as you make them Setting up machines Inspecting parts from a supplier Pierre Vernier described his sliding scale in 1631, for reading astronomical instruments more finely than their main markings.","why":""},{"t":"d","u":"design/gdt-position.html","n":"GD&T: Position Tolerance","c":"Tolerances and GD&T","d":"Why a round tolerance zone accepts more good parts than a ± box, and how a bigger hole earns bonus tolerance","k":"gd&t gdt position true position tolerance zone mmc lmc rfs bonus tolerance feature control frame datum hole pattern parker","w":"","o":null,"x":"A hole drawn with ± tolerances in X and Y has a square zone: its centre may be anywhere inside a little box around the exact position. A mating pin does not care which way the hole is off, only how far. Every point the same distance from the exact position fits equally well, so the honest zone is a circle. Position tolerance (⌖) uses that circle. The circle that just contains a ±0.1 box has a diameter of 0.28 (2 × 0.1 × √2). It accepts every part the box accepts, plus about 57 % more area, and every one of those extra parts still assembles. At maximum material condition (Ⓜ) the stated zone applies to the smallest allowed hole. A hole that comes out bigger can be further off and still clear the pin, so it gets a bonus: its zone grows by however much bigger it is. Try it: change the tolerance and how scattered the drilling is. Each dot is one part off the machine: dark dots pass both ways, blue dots pass only with position, red dots fail. Bolt and dowel hole patterns that must line up with a mating part Talking to a machine shop about which parts to accept Cutting scrap without changing the machine Stanley Parker found the problem in 1940 at the Royal Torpedo Factory in Alexandria, Scotland: inspectors were throwing away parts that assembled perfectly because their holes fell in the corners outside the square ± zone.","why":""},{"t":"d","u":"design/tolerance-stackup.html","n":"Tolerance Stack-Up","c":"Tolerances and GD&T","d":"Add up the small errors in a row of parts to see whether the gap at the end can close up or open too far","k":"tolerance stack up stackup stack-up worst case rss root sum square statistical tolerance analysis gap clearance interference chain","w":"","o":null,"x":"Parts placed end to end add their sizes, and their errors add too. The gap left at the end of the row is what decides whether things fit. Worst case: assume every part comes out at its worst at the same time. The gap can vary by the sum of all the ± tolerances. It always works, but it forces tight, expensive tolerances when there are many parts. Statistical (RSS, root sum of squares): real parts are rarely all at their limits together. If the errors are random and independent, the gap varies by about √(t₁² + t₂² + …), which is much less for many parts. Good to know: RSS is a bet on your suppliers. Use it for large batches from steady processes; use worst case for a few parts, safety-critical fits, or parts from one batch that may all be off the same way. Try it: change the tolerance on the blocks and on the housing, and the number of blocks. The bar under the drawing shows the gap range both ways. Checking that a stack of parts, bearings and spacers fits in a housing Choosing which tolerances to tighten (the biggest ones in the stack) Deciding when a shim or adjuster is cheaper than tight tolerances The RSS method rests on the same maths as dice: roll one die and every total is equally likely, roll ten and the total almost always lands near the middle.","why":""},{"t":"d","u":"design/design-for-manufacturing.html","n":"Design for Manufacturing (DFM)","c":"Design for making","d":"Choose the material, starting stock, tolerances and finish that make a part cheap and easy to make","k":"dfm design for manufacturing manufacturability machinability cost material raw stock near net shape buy to fly tolerance finish finishing anodising batch setup scrap cnc quote","w":"","o":null,"x":"Design for manufacturing (DFM) means designing a part so it costs less to make and is easier to make. The two usually go together: a step the shop does not need is time and money saved. Material: some metals cost more per kilo and are also slower to cut. Brass and aluminium machine quickly; stainless steel is tough on cutters and can take three or four times as long. Form of the raw material: the shop starts from a block, a plate or a ready-made profile. The closer the stock is to the finished shape (near net shape), the less metal is bought, cut away and thrown out as chips. Tolerances: every tighter decimal means slower finishing passes, more careful setup, more inspection and more scrapped parts. Put tight tolerances only on the faces that fit something; leave the rest at the shop's standard. Secondary processing: finishing such as bead blasting, anodising, plating or polishing is a second trip, often to another company. Ask for it only where it does a job: corrosion, wear, looks. Batch size: setup (programming, fixturing, first-part checks) is paid once per batch, so it shrinks per part as the quantity grows. Try it: follow one bracket through the line from raw stock to finished part. Change the material, the stock, the tolerance, the finish and the quantity, and watch the waste pile and the cost bar. Getting cheaper, faster quotes before a drawing goes out Choosing stock and material with the shop, not after it Deciding which tolerances and finishes are really needed Aircraft makers measure waste as the buy-to-fly ratio: kilos of metal bought for each kilo that flies. Titanium parts machined from solid blocks often run 10:1 or worse, so 90 % of very expensive metal leaves the factory as chips.","why":""},{"t":"d","u":"design/design-for-assembly.html","n":"Design for Assembly (DFA)","c":"Design for making","d":"Design a product so it goes together quickly and cheaply: fewer parts, and parts that are easy to pick up, turn the right way and fit","k":"dfa design for assembly boothroyd dewhurst part count fasteners screws snap fit design efficiency assembly time","w":"","o":null,"x":"Design for assembly (DFA) means designing a product with putting it together in mind. Every part has to be picked up, moved, turned the right way round and fitted, and every second of that is paid for. The biggest lever is the number of parts. Fewer parts means fewer steps, so the product is quicker and cheaper to assemble. The parts that remain should be easy to handle: easy to grip, symmetric or clearly one-way so they need no turning, and with chamfers or guides so they drop into place. Screws are the slowest of all: each one is picked, started, driven and checked. Fewer parts also means fewer parts to buy, stock, inspect and keep track of. This saving on the parts themselves is usually where most of the money is made, more than the assembly time. To find parts that can go, ask three questions of each: does it move relative to the others? Must it be a different material? Must it be separate so the product can be put together or serviced? If all three answers are no, it can be merged into a neighbour. Design efficiency compares the real assembly time with an ideal of 3 seconds for each part that must exist. Typical products score 5 to 20 %; a well-designed one can pass 50 %. Try it: change the number of lid screws, swap screws for snap fits, mould the bracket into the base and key the parts. Watch the part count, the assembly time and the cost of parts and labour. Cutting assembly time and cost before tooling is made Products built in large numbers, or by hand Making repairs and servicing simpler IBM designed its 1985 Proprinter with these methods: it snapped together from the top with no screws or springs, and became a textbook example of design for assembly.","why":""},{"t":"c","u":"design/dxf-check.html","n":"Check a DXF for manufacturing","c":"Tool","d":"Load a flat part drawing and see how to make it: process, material, stock, tolerances, finishing and what to fix.","k":"dxf check upload dfm manufacturability laser waterjet router plasma punch stamping material thickness stock sheet tolerance finish drawing file","x":""},{"t":"c","u":"design/stl-check.html","n":"Check an STL for manufacturing","c":"Tool","d":"Load a 3D model and see how to make it: milling, turning, 3D printing, moulding, casting or sheet, and what to fix.","k":"stl check upload 3d model mesh dfm manufacturability cnc milling turning lathe 3d print fdm sla sls mjf dmls injection moulding molding casting wall thickness overhang support undercut draft","x":""},{"t":"c","u":"combine.html","n":"Combine mechanisms","c":"Tool","d":"Chain mechanisms so the output of one drives the next, and see the motion that comes out of the end.","k":"combine chain stages compound gearbox gear train reduction connect link together drive output of one into another","x":""},{"t":"c","u":"combine.html#%5B%7B%22s%22%3A%22spur-gears%22%2C%22p%22%3A%7B%22n1%22%3A10%2C%22n2%22%3A30%7D%7D%2C%7B%22s%22%3A%22slider-crank%22%2C%22p%22%3A%7B%7D%7D%5D","n":"Gear reduction into a piston","c":"Combine","d":"A fast motor slowed 3 to 1, then turned into a back-and-forth stroke.","k":"reduction piston slow down stroke engine pump gears crank combine chain","x":""},{"t":"c","u":"combine.html#%5B%7B%22s%22%3A%22geneva-drive%22%2C%22p%22%3A%7B%7D%7D%2C%7B%22s%22%3A%22spur-gears%22%2C%22p%22%3A%7B%22n1%22%3A12%2C%22n2%22%3A24%7D%7D%2C%7B%22s%22%3A%22rack-pinion%22%2C%22p%22%3A%7B%22n%22%3A14%7D%7D%5D","n":"Stepped linear feed","c":"Combine","d":"A Geneva wheel steps a gear pair, which pushes a rack forward one jump at a time.","k":"indexing feed step linear rack advance conveyor intermittent combine chain","x":""},{"t":"c","u":"combine.html#%5B%7B%22s%22%3A%22worm-gear%22%2C%22p%22%3A%7B%22n%22%3A12%2C%22starts%22%3A1%7D%7D%2C%7B%22s%22%3A%22cam-follower%22%2C%22p%22%3A%7B%7D%7D%5D","n":"Worm-driven cam","c":"Combine","d":"A worm slows the motor right down, so the cam makes one slow, deliberate cycle.","k":"worm cam slow cycle follower timer combine chain","x":""},{"t":"c","u":"combine.html#%5B%7B%22s%22%3A%22belt-pulleys%22%2C%22p%22%3A%7B%22r2%22%3A100%7D%7D%2C%7B%22s%22%3A%22quick-return%22%2C%22p%22%3A%7B%7D%7D%5D","n":"Belt drive into a quick-return ram","c":"Combine","d":"A belt reduction feeds a shaper-style ram that cuts slowly and returns fast.","k":"belt shaper quick return ram cutting stroke combine chain","x":""},{"t":"c","u":"combine.html#%5B%7B%22s%22%3A%22planetary-gears%22%2C%22p%22%3A%7B%22mode%22%3A0%7D%7D%2C%7B%22s%22%3A%22scotch-yoke%22%2C%22p%22%3A%7B%7D%7D%5D","n":"Planetary gearbox into a Scotch yoke","c":"Combine","d":"A compact planetary reduction drives a pure sine-wave slider.","k":"planetary gearbox scotch yoke sine slider compact combine chain","x":""},{"t":"c","u":"combine.html#%5B%7B%22s%22%3A%22spur-gears%22%2C%22p%22%3A%7B%22n1%22%3A12%2C%22n2%22%3A36%7D%7D%2C%7B%22s%22%3A%22spur-gears%22%2C%22p%22%3A%7B%22n1%22%3A12%2C%22n2%22%3A36%7D%7D%2C%7B%22s%22%3A%22spur-gears%22%2C%22p%22%3A%7B%22n1%22%3A12%2C%22n2%22%3A24%7D%7D%5D","n":"Compound gear reduction","c":"Combine","d":"Three gear pairs in a row. Watch the ratios multiply: 3, then 3, then 2.","k":"compound gear train reduction ratio multiply gearbox stages combine chain","x":""},{"t":"c","u":"combine.html#%5B%7B%22s%22%3A%22roller-chain%22%2C%22p%22%3A%7B%22n1%22%3A14%2C%22n2%22%3A28%7D%7D%2C%7B%22s%22%3A%22geneva-drive%22%2C%22p%22%3A%7B%7D%7D%5D","n":"Chain drive into an indexer","c":"Combine","d":"A chain halves the speed, then a Geneva wheel turns it into exact steps.","k":"chain sprocket geneva indexing stop go table combine chain","x":""},{"t":"c","u":"combine.html#%5B%7B%22s%22%3A%22spur-gears%22%2C%22p%22%3A%7B%22n1%22%3A10%2C%22n2%22%3A20%7D%7D%2C%7B%22s%22%3A%22jansen-linkage%22%2C%22p%22%3A%7B%7D%7D%5D","n":"Geared walking leg","c":"Combine","d":"A 2 to 1 reduction slows the motor so the Jansen leg takes unhurried steps.","k":"jansen walking leg strandbeest robot geared slow combine chain","x":""}],"goals":["Turn rotation into back-and-forth","Slow down and gain force","Turn the motion through an angle","Connect shafts that are far apart","Move in steps with pauses","Draw a straight line or an ellipse","Make something walk","Lift or pull a load","Work slowly, return quickly","Allow one direction only, or hold a position","Join shafts that do not line up","Share one drive between two outputs","Hold, locate or support parts","Join parts without bought fasteners","Make a part that comes out right","Make a part to laser cut or 3D print"]};
